-- ═══════════════════════════ 20260905_01_enable_rls_users.sql ═══════════════════════════

-- 2026-09-05 P0-3: public.users 가 anon 키로 그대로 읽혔다 (이름·이메일 평문 노출).
--
-- 앱은 users 를 NextAuth 콜백에서만 만지고, 그 두 곳 모두 service_role 클라이언트를 쓴다
-- (src/app/api/auth/[...nextauth]/route.ts:22, :45). service_role 은 RLS 를 우회하므로
-- 로그인 경로는 영향을 받지 않는다.
--
-- 정책은 만들지 않는다. 인증이 NextAuth JWT 전략이라 Supabase 의 auth.uid() 는 항상 NULL 이고,
-- RLS 를 켜고 정책이 하나도 없으면 anon 은 전면 차단된다. 이게 의도한 상태다.
--
-- 파일명 프리픽스: 기존 add_*.sql 이 init_schema.sql 보다 알파벳순으로 앞이라
-- 인스턴스를 재구축하면 순서가 깨진다. 이후 마이그레이션은 날짜 프리픽스를 붙인다.

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;


-- ═══════════════════════════ 20260906_02_web_widget.sql ═══════════════════════════

-- 웹 위젯 → 받은편지함 → 묶음 PR → 되돌림
-- 설계: docs/07-위젯/웹-위젯-루프-설계.md §4
--
-- 기존 카카오·텔레그램 경로와 대시보드 통계를 건드리지 않도록 **추가만** 한다.
-- messages = 유저가 보낸 것, responses = 우리가 보낸 것 이라는 기존 구분은 그대로 두고
-- conversation_id 로 묶어 타임라인을 만든다.

-- ── 대화 단위 ────────────────────────────────────────
-- 웹 위젯 방문자 1명 = 대화 1개, 카카오 유저 1명 = 대화 1개

CREATE TABLE conversations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  bot_id UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  source TEXT NOT NULL,                 -- web | kakao | telegram
  external_user_id TEXT NOT NULL,       -- visitorId | botUserKey | chat_id
  contact_name TEXT,
  contact_email TEXT,
  contact_phone TEXT,
  status TEXT NOT NULL DEFAULT 'open',  -- open | closed
  last_message_at TIMESTAMPTZ,
  operator_read_at TIMESTAMPTZ,         -- 받은편지함 미읽음 판정
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE (bot_id, source, external_user_id)
);

ALTER TABLE messages  ADD COLUMN conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE;
ALTER TABLE responses ADD COLUMN conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE;

-- NULL 이면 아직 유저에게 못 보낸 것 = 카카오 대기열.
-- 운영자 답장과 되돌림이 같은 큐를 쓴다.
ALTER TABLE responses ADD COLUMN delivered_at TIMESTAMPTZ;
ALTER TABLE responses ADD COLUMN auto_dev_run_id UUID REFERENCES auto_dev_runs(id) ON DELETE SET NULL;
-- response_type 값 추가: ai | operator | loop_closed (기존 mention|keyword|question|kakao 유지)

-- ── 피드백 묶음 ──────────────────────────────────────
-- 비슷한 피드백을 묶어 묶음당 PR 1개를 만든다

CREATE TABLE insight_groups (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  bot_id UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  title TEXT NOT NULL,                  -- "쿠폰 페이지에서 적용 버튼이 안 눌림"
  summary TEXT NOT NULL,                -- PR 프롬프트에 들어갈 종합 설명
  category TEXT NOT NULL,               -- insights.category 와 같은 값
  status TEXT NOT NULL DEFAULT 'open',  -- open | pr_created | merged | dismissed
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE insights      ADD COLUMN group_id UUID REFERENCES insight_groups(id) ON DELETE SET NULL;
ALTER TABLE auto_dev_runs ADD COLUMN group_id UUID REFERENCES insight_groups(id) ON DELETE SET NULL;
ALTER TABLE auto_dev_runs ADD COLUMN merged_at TIMESTAMPTZ;

-- ── 봇 설정 ─────────────────────────────────────────

ALTER TABLE bots ADD COLUMN pr_mode TEXT NOT NULL DEFAULT 'approve';  -- approve | auto
ALTER TABLE bots ADD COLUMN widget_connected_at TIMESTAMPTZ;

-- ── 인덱스 ──────────────────────────────────────────

CREATE INDEX idx_conv_bot_last ON conversations(bot_id, last_message_at DESC);
CREATE INDEX idx_msg_conv ON messages(conversation_id);
CREATE INDEX idx_resp_conv ON responses(conversation_id);
-- 카카오 웹훅이 매 발화마다 때리는 경로 — 미전달분만 인덱싱한다
CREATE INDEX idx_resp_undelivered ON responses(conversation_id) WHERE delivered_at IS NULL;
CREATE INDEX idx_insight_group ON insights(group_id);
CREATE INDEX idx_group_bot ON insight_groups(bot_id, status);

-- ── RLS ─────────────────────────────────────────────
-- 기존 테이블과 같은 패턴: 봇 소유자만. 라우트는 service_role 을 쓰므로 우회되지만,
-- anon 키로 직접 REST 를 때리는 경로를 막는다.

ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_owner ON conversations FOR ALL
  USING (bot_id IN (SELECT id FROM bots WHERE user_id = auth.uid()));

ALTER TABLE insight_groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY insight_groups_owner ON insight_groups FOR ALL
  USING (bot_id IN (SELECT id FROM bots WHERE user_id = auth.uid()));

-- ── 기존 데이터 백필 ────────────────────────────────
--
-- 이미 들어와 있는 카카오 실데이터(메시지 4·응답 4)가 받은편지함과 타임라인에서
-- 사라지지 않도록 대화에 연결한다. 시연이 이 실데이터 위에서 돈다.

-- 1) 기존 메시지의 (봇, 채널, 외부유저) 조합마다 대화를 만든다
INSERT INTO conversations (bot_id, source, external_user_id, last_message_at, created_at)
SELECT
  m.bot_id,
  m.source,
  m.external_user_id,
  MAX(m.detected_at),
  MIN(m.detected_at)
FROM messages m
WHERE m.external_user_id IS NOT NULL
GROUP BY m.bot_id, m.source, m.external_user_id
ON CONFLICT (bot_id, source, external_user_id) DO NOTHING;

-- 2) 메시지를 대화에 연결
UPDATE messages m
SET conversation_id = c.id
FROM conversations c
WHERE m.conversation_id IS NULL
  AND m.external_user_id IS NOT NULL
  AND c.bot_id = m.bot_id
  AND c.source = m.source
  AND c.external_user_id = m.external_user_id;

-- 3) 응답을 트리거 메시지를 통해 같은 대화에 연결
UPDATE responses r
SET conversation_id = m.conversation_id
FROM messages m
WHERE r.conversation_id IS NULL
  AND r.trigger_message_id = m.id
  AND m.conversation_id IS NOT NULL;

-- 4) **중요** — 기존 응답은 이미 유저에게 나간 것이다.
--    delivered_at 을 채우지 않으면 새로 생긴 미전달 인덱스가 이것들을 대기열로 보고,
--    그 유저가 다음에 말을 걸 때 옛날 답변이 한꺼번에 쏟아진다.
UPDATE responses
SET delivered_at = COALESCE(sent_at, now())
WHERE delivered_at IS NULL;


-- ═══════════════════════════ 20260906_03_widget_appearance.sql ═══════════════════════════

-- 웹 위젯 모양 + 되돌림 확인 — 설계 §4 의 잔여분
--
-- 20260906_02_web_widget.sql 이 §4 의 대화·묶음·대기열 부분을 적용했고,
-- "봇 설정 › 위젯 모양"(목업 8번)과 "되돌림 확인 2버튼" 컬럼이 빠져 있었다.
-- 위젯이 부팅 시 `GET /api/widget/[botId]/config` 로 읽는 값들이다.
-- 전부 NULL 허용이라 기존 봇은 service_name 등으로 폴백한다.

ALTER TABLE bots ADD COLUMN profile_image_url TEXT;      -- Supabase Storage public URL (bot-profiles/<botId>.<ext>)
ALTER TABLE bots ADD COLUMN display_name TEXT;           -- NULL 이면 service_name
ALTER TABLE bots ADD COLUMN status_text TEXT DEFAULT '보통 몇 분 안에 답해요';
ALTER TABLE bots ADD COLUMN greeting TEXT;               -- 첫 인사말. NULL 이면 위젯 기본 문구
ALTER TABLE bots ADD COLUMN operator_display_name TEXT;  -- 운영자 답장 이름 (예: "널널투어 팀 · 누리")

-- 되돌림(loop_closed) 카드에서 유저가 누른 버튼. 단계 4 의 /confirm 이 채운다.
ALTER TABLE responses ADD COLUMN user_confirmation TEXT; -- fixed | not_fixed | NULL
ALTER TABLE responses ADD COLUMN user_confirmed_at TIMESTAMPTZ;


-- ═══════════════════════════ 20260906_04_rls_rest.sql ═══════════════════════════

-- 2026-09-06 P0-3 나머지: RLS 가 꺼져 있던 6개 테이블.
--
-- accounts·sessions 는 NextAuth 어댑터 테이블이고 코드는 service_role 로만 만진다.
-- cooldown_state·feedbacks·classifications·action_logs 는 A3(B계열 제거, 커밋 3a67a25)
-- 이후 코드 참조가 0건이다. 테이블은 남아 있지만 anon 키로 읽히면 안 된다.
--
-- 20260905_01_enable_rls_users.sql 과 같은 원칙: 정책은 만들지 않는다.
-- 인증이 NextAuth JWT 라 auth.uid() 는 항상 NULL 이고, 정책 0개 + RLS on = anon 전면 차단.
-- 앱 경로는 전부 service_role 이라 영향이 없다 (2026-09-06 실측 6개 테이블 전부 0행).

ALTER TABLE public.accounts        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sessions        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cooldown_state  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feedbacks       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.classifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.action_logs     ENABLE ROW LEVEL SECURITY;


-- ═══════════════════════════ 20260906_05_run_closed_at.sql ═══════════════════════════

-- 머지 없이 닫힌 PR 을 기록한다 (2026-09-06).
-- 머지 감지는 merged_at 만 봤기 때문에 GitHub 에서 닫아버린 PR(리허설 중복 PR #4)이 화면에 영원히 「열림」으로 남았다.
-- checkMergedRuns 가 GitHub state=closed && merged=false 를 보면 여기 시각을 찍고, 화면은 「닫힘」으로 그린다.
ALTER TABLE auto_dev_runs ADD COLUMN IF NOT EXISTS closed_at TIMESTAMPTZ;


-- ═══════════════════════════ 20260908_01_message_context.sql ═══════════════════════════

-- 위젯이 함께 보내는 기술 맥락 (Gleap 차용 P0-1).
--
-- 왜: 지금까지 자동 PR 은 "쿠폰 버튼이 안 눌려요" 라는 문장 하나만 보고
-- 레포 전체에서 고칠 파일을 찾았다. 어느 페이지에서 났는지조차 몰랐다.
-- 리허설에서 묶음 3개 중 2개가 "고칠 파일이 없다" 로 중단된 것과 무관하지 않다.
--
-- 담기는 것: 페이지 URL(민감 쿼리 마스킹됨) · 브라우저 · 뷰포트 ·
-- 위젯 로드 후 발생한 콘솔 에러 · 실패한 네트워크 요청.
-- 전부 선택이다. 위젯이 안 보내도 기존 흐름은 그대로 돈다.

alter table messages add column if not exists context jsonb;

comment on column messages.context is
  '위젯이 수집한 기술 맥락(URL·UA·뷰포트·콘솔 에러·실패 요청). 서버에서 마스킹·상한 적용됨. 카카오 등 다른 채널은 null.';


-- ═══════════════════════════ 20260908_02_group_spec_draft.sql ═══════════════════════════

-- 기능 요청 묶음의 스펙 초안 (Gleap 차용 P1-3).
--
-- 기능 요청에 코드 수정 PR 을 여는 것은 대개 틀린 답이다 — 무엇을 만들지는
-- 사람이 정해야 한다. 대신 "여러 사람이 말한 요청" 을 읽을 수 있는 스펙 초안으로
-- 정리해 두고, 만들지 말지는 운영자가 판단한다.

alter table insight_groups add column if not exists spec_draft text;
alter table insight_groups add column if not exists spec_drafted_at timestamptz;

comment on column insight_groups.spec_draft is
  '기능 요청 묶음의 스펙 초안(마크다운). 사람이 읽고 판단하는 재료이지 실행 지시가 아니다.';


-- ═══════════════════════════ 20260909_01_run_close_reason.sql ═══════════════════════════

-- 머지 없이 닫힌 PR 의 사유를 기록한다 (2026-09-10).
--
-- closed_at 은 GitHub 상태(state=closed && !merged)를 보고 자동으로 찍히지만, 왜 닫혔는지는
-- GitHub 가 모른다. 경로를 지어냈는지(PR #1·#5), 실재 파일을 고쳤으나 인과가 틀렸는지(PR #6),
-- 중복이었는지(PR #4)는 사람만 안다. 사유는 「수정 PR」 화면에서 사람이 고른다.
-- 사유가 쌓이면 어떤 실패가 반복되는지 보이고, 그게 다음 방어의 근거가 된다.
--
-- 컬럼 추가만. 기존 행은 NULL(미분류)로 남는다.

ALTER TABLE auto_dev_runs
  ADD COLUMN IF NOT EXISTS close_reason TEXT
    CHECK (close_reason IN ('hallucinated_path', 'wrong_causality', 'duplicate', 'superseded', 'other'));

ALTER TABLE auto_dev_runs
  ADD COLUMN IF NOT EXISTS close_note TEXT;

COMMENT ON COLUMN auto_dev_runs.close_reason IS
  '머지 없이 닫힌 이유. 사람이 화면에서 고른다. NULL = 미분류';
COMMENT ON COLUMN auto_dev_runs.close_note IS
  '사유에 붙이는 짧은 메모 (500자 이하, 애플리케이션이 검증)';

-- 기존 닫힌 run 2건 백필 — QA 로 사유가 확정된 것들이다.
-- PR #4 (2026-09-06 리허설): 카카오 후속 문의가 별도 묶음이 돼 실수로 만든 중복. useCallback·주석뿐인 무의미한 변경.
-- PR #6 (2026-09-09 QA): coupon-session.ts 가 이미 막고 있는 실패에 도달 불가능한 else 분기를 추가. 고칠 버그가 없었다.
UPDATE auto_dev_runs
SET close_reason = 'duplicate',
    close_note = '리허설 중 후속 문의 묶음에 실수로 생성. useCallback·주석뿐인 무의미한 변경'
WHERE pr_number = 4
  AND pr_url LIKE 'https://github.com/wineny/nullnul-tour-demo/%'
  AND closed_at IS NOT NULL AND merged_at IS NULL AND close_reason IS NULL;

UPDATE auto_dev_runs
SET close_reason = 'wrong_causality',
    close_note = 'coupon-session.ts:58·60 이 이미 막는 실패에 도달 불가능한 분기 추가. 고칠 버그가 존재하지 않았다'
WHERE pr_number = 6
  AND pr_url LIKE 'https://github.com/wineny/nullnul-tour-demo/%'
  AND closed_at IS NOT NULL AND merged_at IS NULL AND close_reason IS NULL;


-- ═══════════════════════════ 20260910_01_bot_knowledge_byok.sql ═══════════════════════════

-- ── 답변 지식 (롱컨텍스트 스터핑용). 검색 인덱스 없음 — 통째로 프롬프트에 들어간다.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS knowledge_text TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS knowledge_faq JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS knowledge_updated_at TIMESTAMPTZ;

-- ── BYOK. llm_provider / llm_api_key_encrypted 는 init_schema.sql:55-56 에 이미 있다(사용처 0) — 재사용.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS llm_key_last4 TEXT;            -- 화면 표시용. 원문은 절대 안 나간다
ALTER TABLE bots ADD COLUMN IF NOT EXISTS llm_key_verified_at TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS llm_key_failed_at TIMESTAMPTZ; -- 마지막 호출 실패 시각
ALTER TABLE bots ADD COLUMN IF NOT EXISTS daily_reply_limit INTEGER;     -- NULL = 기본값(키없음 30 / gemini 300 / 그 외 100)
-- 운영자가 고른 모델. NULL = 그 provider 의 추천 기본값(src/lib/llm/models.ts).
-- CHECK 를 걸지 않는다 — provider 가 새 모델을 내놓을 때마다 마이그레이션을 하게 된다.
-- 유효성은 첫 호출이 판정하고, 실패하면 llm_key_failed_at 경로로 운영자에게 보인다(§B-5).
ALTER TABLE bots ADD COLUMN IF NOT EXISTS llm_model TEXT;

-- ── AI 가 못 답한 대화 표시 (§A-4). 운영자가 답장하면 NULL 로 되돌린다.
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS escalated_at TIMESTAMPTZ;

-- ── 요청 출처 기록 (§B-7). 차단하지 않는다 — 사후 판별용.
ALTER TABLE messages ADD COLUMN IF NOT EXISTS origin TEXT;

-- ── 일일 사용량. cooldown_state 를 건드리지 않기 위해 별도 테이블로 둔다.
--    (cooldown_state 는 텔레그램 전용이고 last_response_at 30초 간격 로직과 결합돼 있다.
--     위젯 트래픽을 거기 섞으면 텔레그램 봇이 조용히 막힌다 — 기존 동작 변경 = P4 위반)
CREATE TABLE IF NOT EXISTS bot_usage (
  bot_id            UUID    NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  usage_date        DATE    NOT NULL,
  -- 이름이 "시도"인 이유: 선증가 후판정이라 LLM 호출이 실패해도 1 이 올라간다.
  -- 이 값은 "성공한 AI 응답 수"가 아니다 — 화면에 "AI 응답 N건" 으로 표시하지 말 것.
  -- 응답 건수를 보여주려면 responses 를 세야 한다.
  ai_call_attempts  INTEGER NOT NULL DEFAULT 0,
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (bot_id, usage_date)
);
-- 인덱스 추가 없음: PK (bot_id, usage_date) 가 유일한 조회 경로다.
-- 정책 없는 RLS = anon 전면 차단. 20260906_04_rls_rest.sql 관례를 따른다.
ALTER TABLE bot_usage ENABLE ROW LEVEL SECURITY;

-- 원자 증가. Supabase JS 의 upsert() 로는 "현재값 + 1" 을 표현할 수 없어 함수로 둔다.
-- SECURITY DEFINER 를 붙이지 않는다 — service_role 로만 호출하므로 불필요하고 공격면만 는다.
-- 날짜 경계는 KST. (cooldown_state 는 UTC 자정 = KST 09:00 에 리셋된다. 그 문제를 여기서 안 물려받는다)
CREATE OR REPLACE FUNCTION bump_bot_usage(p_bot_id UUID)
RETURNS INTEGER
LANGUAGE sql
AS $$
  INSERT INTO bot_usage (bot_id, usage_date, ai_call_attempts)
  VALUES (p_bot_id, (now() AT TIME ZONE 'Asia/Seoul')::date, 1)
  ON CONFLICT (bot_id, usage_date)
  DO UPDATE SET ai_call_attempts = bot_usage.ai_call_attempts + 1, updated_at = now()
  RETURNING ai_call_attempts;
$$;

-- 선제 조치. 지금은 SECURITY INVOKER 라 anon 이 불러도 bot_usage 의 RLS 가 막는다 —
-- 즉 현재 뚫려 있다는 뜻이 아니다. 다만 나중에 누군가 성능이나 편의를 이유로
-- SECURITY DEFINER 를 붙이는 순간, PUBLIC EXECUTE 가 남아 있으면 그날로 구멍이 된다
-- (익명이 임의 botId 로 남의 카운터를 올려 상한을 소진시킬 수 있다).
-- 실행 권한을 service_role 로 좁혀 그 사고 경로를 미리 닫는다.
-- ⚠️ FROM PUBLIC 만으로는 부족하다(2026-09-10 실측). Supabase 는 public 스키마 신규 함수에
--    anon·authenticated 에게 EXECUTE 를 «명시적으로» 준다(ALTER DEFAULT PRIVILEGES).
--    PUBLIC 만 회수하면 proacl 에 anon=X/authenticated=X 가 그대로 남는다 — 셋 다 회수해야 한다.
REVOKE EXECUTE ON FUNCTION bump_bot_usage(UUID) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION bump_bot_usage(UUID) FROM anon;
REVOKE EXECUTE ON FUNCTION bump_bot_usage(UUID) FROM authenticated;
GRANT  EXECUTE ON FUNCTION bump_bot_usage(UUID) TO service_role;


-- ═══════════════════════════ 20260910_02_llm_key_failed_reason.sql ═══════════════════════════

-- 즉답 LLM 호출이 실패한 «사유» 를 담는 전용 컬럼 (계획 §B-6).
--
-- 왜 status_message 를 안 쓰나: 그 컬럼은 «연결 상태» 전용이다.
-- lib/bot/db.ts 의 markBotConnected() 가 status_message = NULL 을 쓰고,
-- api/kakao/webhook/[botId]/route.ts 가 카카오 메시지마다 after() 로 그걸 부른다.
-- 거기에 키 실패 문구를 넣으면 (1) 다음 발화에 지워지고
-- (2) /api/bots/[id]/status 를 읽는 연결 화면에 «연결 문제»처럼 뜬다.
-- markBotConnected 를 고치는 건 기존 동작 변경이라 하지 않는다 — 컬럼을 하나 늘린다.
--
-- 값은 lib/llm/key.ts 의 failureMessage() 가 만든 4분류 «고정 문자열» 만 들어간다.
-- provider 에러 원문은 절대 넣지 않는다 — 키 조각이나 내부 정보가 섞일 수 있다.
-- 배지 판정은 llm_key_failed_at 이 하고, 이 컬럼은 문구만 담당한다.
-- 초기화 시점은 «키 교체·모델 변경 저장» 이다. 호출이 성공할 때마다 쓰면
-- 메시지당 DB 왕복이 하나 는다(위젯 POST 는 메시지마다 이 경로를 탄다).
ALTER TABLE bots ADD COLUMN IF NOT EXISTS llm_key_failed_reason TEXT;


-- ═══════════════════════════ 20260910_03_kakao_usage.sql ═══════════════════════════

-- 카카오 호출을 «따로» 센다.
--
-- 왜 나누나: 카카오는 계측만 하고 차단하지 않는다(4초 예산 + 오픈빌더 1:1 채널이라
-- 익명 스크립트가 때릴 수 있는 위젯 POST 와 노출 성격이 다르다).
-- 그런데 같은 카운터(ai_call_attempts)에 얹으면 «차단당하지 않는 트래픽이
-- 차단당하는 트래픽의 상한을 잠식»한다 — 카카오 대화가 활발한 날에는 위젯이
-- 아무 잘못 없이 조용히 막힌다. 세는 칸을 나눠 그 결합을 끊는다.
--
-- ai_call_attempts 와 마찬가지로 이름이 "시도"인 이유: 선증가라 실패해도 1 이 올라간다.
-- "성공한 카카오 응답 수"가 아니다 — 화면에 그렇게 쓰지 말 것.
ALTER TABLE bot_usage ADD COLUMN IF NOT EXISTS kakao_call_attempts INTEGER NOT NULL DEFAULT 0;

-- bump_bot_usage 와 같은 upsert 패턴. 날짜 경계도 같은 KST 다.
-- SECURITY DEFINER 를 붙이지 않는다 — service_role 로만 호출하므로 불필요하고 공격면만 는다.
CREATE OR REPLACE FUNCTION bump_kakao_usage(p_bot_id UUID)
RETURNS INTEGER
LANGUAGE sql
AS $$
  INSERT INTO bot_usage (bot_id, usage_date, kakao_call_attempts)
  VALUES (p_bot_id, (now() AT TIME ZONE 'Asia/Seoul')::date, 1)
  ON CONFLICT (bot_id, usage_date)
  DO UPDATE SET kakao_call_attempts = bot_usage.kakao_call_attempts + 1, updated_at = now()
  RETURNING kakao_call_attempts;
$$;

-- bump_bot_usage 와 같은 이유로 실행 권한을 좁힌다. 지금은 SECURITY INVOKER 라
-- bot_usage 의 RLS 가 막지만, 나중에 누군가 DEFINER 를 붙이는 순간 PUBLIC EXECUTE 가
-- 남아 있으면 그날로 구멍이 된다.
REVOKE EXECUTE ON FUNCTION bump_kakao_usage(UUID) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION bump_kakao_usage(UUID) FROM anon;
REVOKE EXECUTE ON FUNCTION bump_kakao_usage(UUID) FROM authenticated;
GRANT  EXECUTE ON FUNCTION bump_kakao_usage(UUID) TO service_role;


-- ═══════════════════════════ 20260910_04_channel_talk.sql ═══════════════════════════

-- 채널톡(Channel.io) 웹훅 연동 (2026-09-10). 추가만.

-- 대화: 채널톡 유저챗 1개 = 대화 1개. external_user_id = chatId.
-- channel_person_id 는 장식이 아니다 — 되돌림 person 당 1건과 묶음 「몇 명」 통계가 읽는다.
-- personId 를 못 얻으면 'chat:'||chatId 폴백을 넣어 NULL 을 남기지 않는다(애플리케이션 책임).
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS channel_person_id TEXT;
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS channel_chat_type TEXT;      -- userChat | group
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS channel_contact_source TEXT; -- user | veil (veil = 익명, 검증되지 않음)

-- 메시지 멱등: 채널톡이 같은 이벤트를 다시 보내도 인사이트가 두 번 생기지 않게.
-- NULL 은 서로 충돌하지 않으므로 partial 이 아니라 전체 UNIQUE 로 둔다
-- (PostgREST 의 on_conflict 는 partial index 를 추론하지 못한다).
ALTER TABLE messages ADD COLUMN IF NOT EXISTS external_message_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_msg_external
  ON messages(bot_id, source, external_message_id);

-- 웹훅 속도 제한이 200 응답 전에 (bot_id, source, detected_at) 을 센다.
-- 이 인덱스가 없으면 봇당 전량 스캔이라 응답이 느려진다(위젯은 external_user_id 로 좁혀 덜 아프다).
CREATE INDEX IF NOT EXISTS idx_msg_bot_detected ON messages(bot_id, detected_at DESC);

-- 되돌림 전송 결과. delivered_at 은 기존 컬럼을 그대로 쓴다.
ALTER TABLE responses ADD COLUMN IF NOT EXISTS delivery_attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE responses ADD COLUMN IF NOT EXISTS delivery_error TEXT;

-- 봇: 채널톡 자격증명·연결 상태·마지막 오류(after() 실패 계측).
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_access_key_encrypted TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_access_secret_encrypted TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_webhook_token_encrypted TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_id TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_slug TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_webhook_id TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_bot_name TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_connected_at TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_last_error TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_last_error_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_conv_channel_person
  ON conversations(bot_id, channel_person_id) WHERE channel_person_id IS NOT NULL;

-- ── 채널톡 분류 호출을 «따로» 센다 (18c2a65 의 bot_usage 재사용, R4 해소).
--
-- 왜 자기 칸이 필요한가: 채널톡은 무인증 웹훅이고 CS 비중이 높아 하루 수백 건이 들어올 수 있다.
-- 그걸 ai_call_attempts(위젯 즉답 상한)에 얹으면 채널톡이 활발한 날 위젯이 아무 잘못 없이
-- 조용히 막힌다 — 20260910_03 이 카카오에 대해 적어 둔 것과 같은 이유다. 세는 칸을 나눈다.
-- 이름이 "시도"인 것도 같은 이유: 선증가라 LLM 이 실패해도 1 이 올라간다.
ALTER TABLE bot_usage ADD COLUMN IF NOT EXISTS channel_call_attempts INTEGER NOT NULL DEFAULT 0;

-- bump_bot_usage · bump_kakao_usage 와 같은 upsert 패턴. 날짜 경계도 같은 KST 다.
CREATE OR REPLACE FUNCTION bump_channel_usage(p_bot_id UUID)
RETURNS INTEGER
LANGUAGE sql
AS $$
  INSERT INTO bot_usage (bot_id, usage_date, channel_call_attempts)
  VALUES (p_bot_id, (now() AT TIME ZONE 'Asia/Seoul')::date, 1)
  ON CONFLICT (bot_id, usage_date)
  DO UPDATE SET channel_call_attempts = bot_usage.channel_call_attempts + 1, updated_at = now()
  RETURNING channel_call_attempts;
$$;

REVOKE EXECUTE ON FUNCTION bump_channel_usage(UUID) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION bump_channel_usage(UUID) FROM anon;
REVOKE EXECUTE ON FUNCTION bump_channel_usage(UUID) FROM authenticated;
GRANT  EXECUTE ON FUNCTION bump_channel_usage(UUID) TO service_role;

COMMENT ON COLUMN bots.channel_webhook_token_encrypted IS
  '웹훅 URL 마지막 세그먼트의 시크릿. 소유자 인증 GET 으로만 평문이 나가고 로그·목록 API 에는 싣지 않는다';
COMMENT ON COLUMN conversations.channel_contact_source IS
  'veil = 채널톡 익명 유저. 이름·이메일이 검증되지 않은 값임을 표시';
COMMENT ON COLUMN messages.external_message_id IS
  '채널 원본 메시지 id. 웹훅 재전송 멱등 근거. 위젯·카카오는 NULL';


-- ═══════════════════════════ 20260910_05_channel_verify_token.sql ═══════════════════════════

-- 채널톡 웹훅 토큰 대조 (2026-09-10 실계정 검증 후속). 추가만.
--
-- 실계정(E2)에서 확인한 것: 채널톡은 서명 헤더를 보내지 않고, 웹훅을 등록하면 대화상자에
-- 32hex 토큰을 한 번 보여주고 그 뒤 모든 요청에 `?token=<그 값>` 을 붙여 온다.
-- 운영자가 그 값을 연결 화면에 붙여넣으면 두 번째 인증이 된다 — URL 경로의 시크릿 세그먼트가
-- 요청 로그에 남아 새는 경우를 대비한 겹이다. 비어 있으면 대조하지 않는다(종전 동작).
ALTER TABLE bots ADD COLUMN IF NOT EXISTS channel_webhook_verify_token_encrypted TEXT;

COMMENT ON COLUMN bots.channel_webhook_verify_token_encrypted IS
  '채널톡이 웹훅 등록 시 발급해 ?token= 으로 붙여 보내는 값. 운영자가 붙여넣으면 대조하고, NULL 이면 대조하지 않는다. 어떤 응답에도 되돌려 내보내지 않는다';


-- ═══════════════════════════ 20260910_06_widget_colors.sql ═══════════════════════════

-- 위젯 색상 2개 — 운영자가 고르는 강조색·내 말풍선색.
--
-- 20260906_03_widget_appearance.sql 의 "봇 설정 › 위젯 모양" 확장이다.
-- 지금까지 위젯(public/widget.js)은 Feedloop 코랄 #F2645C 과 잉크 #191d1b 를
-- 박아 쓰고 있었다 — 고객 사이트에 붙는 물건인데 우리 브랜드색이 뜬다.
--
-- 둘 다 NULL 허용이고 NULL = 지금까지의 기본색이다. 기존 봇은 아무것도 안 바뀐다.
-- 값은 항상 소문자 #rrggbb 로 정규화해서 넣는다(lib/bot/appearance.ts).
-- 코랄 틴트(#FDF1F0·#FBE2E2)는 저장하지 않는다 — 강조색에서 런타임에 만든다.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS accent_color TEXT;         -- 강조색. NULL 이면 #F2645C
ALTER TABLE bots ADD COLUMN IF NOT EXISTS visitor_bubble_color TEXT; -- 방문자 말풍선 배경. NULL 이면 #191d1b

COMMENT ON COLUMN bots.accent_color IS '위젯 강조색 (#rrggbb 소문자). NULL 이면 Feedloop 기본 코랄 #F2645C. 플로팅 버튼·미읽음 배지·아바타·AI 배지·보내기·링크·되돌림 카드에 쓰인다.';
COMMENT ON COLUMN bots.visitor_bubble_color IS '위젯에서 방문자 자기 말풍선 배경색 (#rrggbb 소문자). NULL 이면 잉크 #191d1b. 글자색은 명도에 따라 흰색/잉크로 자동 선택된다.';


-- ═══════════════════════════ 20260911_01_widget_starter_questions.sql ═══════════════════════════

-- 위젯 첫 화면 「자주 묻는 질문」 칩 — 운영자가 정하는 시작 질문.
--
-- 지금까지 첫 화면 칩은 코드에 박힌 3개(불편·기능·문의)뿐이었다. 봇에 답변 지식이
-- 들어간 뒤로 위젯은 "피드백 수집함"이자 "물어보면 답하는 창구"가 됐는데,
-- 첫 화면이 그 변화를 못 담았다 — 방문자는 물어봐도 된다는 걸 알 길이 없다.
--
-- 운영자가 여기에 실제 질문 문장을 넣으면 그게 칩이 되고, 누르면 바로 전송돼
-- 그 자리에서 답을 받는다. 비워두면 위젯 config 라우트가 knowledge_faq 앞쪽
-- 질문으로 채운다(lib/bot/appearance.ts resolveStarterQuestions).
--
-- NULL 이 아니라 빈 배열이 기본이다 — knowledge_faq 와 같은 모양으로 맞춰
-- 읽는 쪽이 null 검사를 따로 하지 않게 한다. 기존 봇은 빈 배열이라 FAQ 폴백을 탄다.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS starter_questions JSONB NOT NULL DEFAULT '[]'::jsonb;

COMMENT ON COLUMN bots.starter_questions IS '위젯 첫 화면 「자주 묻는 질문」 칩 문장 배열 (문자열 최대 4개, 각 40자). 빈 배열이면 knowledge_faq 앞 3개의 질문으로 폴백한다. 이 값은 무인증 위젯 config 로 나간다.';


-- ═══════════════════════════ 20260911_02_starter_faq_fallback.sql ═══════════════════════════

-- 시작 질문을 「띄우지 않기」로 둘 수 있게 한다.
--
-- 20260911_01 로 첫 화면에 「자주 묻는 질문」 칩이 생기면서, 운영자가 시작 질문을
-- 비워두면 답변 지식 FAQ 앞 3개가 자동으로 방문자에게 보이게 됐다. 편리하지만
-- «끄는 방법이 없었다» — 빈 배열이 곧 「FAQ 로 채워라」라는 뜻이라, 아무것도 안
-- 띄우겠다는 의사를 표현할 자리가 없었다.
--
-- FAQ 질문 문장 자체가 비밀인 경우는 드물지만, 운영자가 내부용 문답을 지식에 넣으면
-- 그 질문이 아무 조작 없이 공개 위젯 첫 화면에 뜬다. 동의한 적 없는 공개다.
--
-- 기본값 true 는 지금 동작 그대로다(설계 결정: 운영자 지정 → 없으면 FAQ 폴백).
-- 기존 봇은 한 곳도 바뀌지 않고, 끄고 싶은 운영자만 위젯 모양 화면에서 끈다.
--
-- 이 컬럼은 «칸이 비었을 때»만 본다. 시작 질문을 직접 써 넣으면 그게 언제나 이긴다.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS starter_faq_fallback BOOLEAN NOT NULL DEFAULT true;

COMMENT ON COLUMN bots.starter_faq_fallback IS '시작 질문(starter_questions)이 비었을 때 knowledge_faq 앞쪽 질문으로 채울지. false 면 위젯 첫 화면에 「자주 묻는 질문」 줄이 뜨지 않는다. 직접 쓴 시작 질문이 있으면 이 값과 무관하게 그게 뜬다.';


-- ═══════════════════════════ 20260911_03_insights_unique_message.sql ═══════════════════════════

-- 한 메시지에 인사이트는 하나.
--
-- 왜 필요한가 — 배치 분류(`/api/classify`)는 「이미 분류됐는가」를 읽고 나서 insert 하는데
-- 그 사이에 원자성이 없다. 화면 버튼은 `setClassifying(true)` 로 잠기지만 탭 두 개나
-- 새로고침이면 두 실행이 같은 미분류 목록을 보고 둘 다 저장한다.
-- 중복이 생기면 묶기에서 같은 제보가 두 번 세어지고, 시연 숫자가 틀어진다.
--
-- `validateClassifications` 는 **한 호출 안의** 중복만 막는다. 호출 사이는 DB 가 막아야 한다.
--
-- 부분 인덱스인 이유: `message_id` 는 nullable 이다(메시지 없이 만들어지는 인사이트가
-- 있을 수 있고, 메시지가 지워지면 ON DELETE CASCADE 로 행도 같이 사라지지만
-- 스키마상 NULL 이 허용된다). NULL 끼리는 UNIQUE 가 충돌하지 않지만, 의도를 분명히 한다.
--
-- 적용 시점 기준 중복 0건 — `select message_id, count(*) from insights group by 1 having count(*)>1` 이 빈 결과.

CREATE UNIQUE INDEX IF NOT EXISTS insights_message_id_unique
  ON insights (message_id)
  WHERE message_id IS NOT NULL;


-- ═══════════════════════════ 20260911_04_insights_unique_message_fix.sql ═══════════════════════════

-- `20260911_03` 의 부분 UNIQUE 인덱스를 일반 UNIQUE 인덱스로 바꾼다.
--
-- 왜 — 부분 인덱스(`WHERE message_id IS NOT NULL`)는 **PostgREST 의 upsert 와 맞물리지
-- 않는다.** `.upsert(rows, { onConflict: 'message_id' })` 는 술어 없이
-- `ON CONFLICT (message_id)` 를 보내는데, Postgres 는 술어가 없는 conflict target 을
-- 부분 인덱스에 매칭해 주지 않는다(42P10). 그래서 `POST /api/classify` 의 insert 가
-- **매번 통째로 실패**했다:
--
--   there is no unique or exclusion constraint matching the ON CONFLICT specification
--
-- 화면에는 `{"classified":0, "failedBots":1}` 로만 보였다. 인덱스를 만든 날부터
-- 운영자 [분류] 버튼은 한 번도 성공한 적이 없다(2026-09-11 프로덕션 DB 로 실측).
--
-- 왜 술어를 그냥 빼도 되나 — **Postgres 의 UNIQUE 는 NULL 끼리를 충돌로 보지 않는다.**
-- `message_id IS NULL` 인 행은 일반 UNIQUE 인덱스에서도 여러 개 들어간다(트랜잭션으로
-- 확인함). 술어는 의도를 적어두려던 것이었고 제약을 더하지 않았다 — 대신 upsert 를 막았다.
--
-- 되돌리려면 이 인덱스를 지우고 `20260911_03` 의 부분 인덱스를 다시 만들면 된다.
-- 단, 그러면 분류 버튼이 다시 멎는다.

DROP INDEX IF EXISTS insights_message_id_unique;

CREATE UNIQUE INDEX IF NOT EXISTS insights_message_id_unique
  ON insights (message_id);


-- ═══════════════════════════ 20260912_01_response_email.sql ═══════════════════════════

-- 응답(운영자 답장 · 되돌림)이 이메일로도 나갔는지 기록한다.
--
-- 위젯이 「…로 답장을 보내드려요」라고 약속하는데 발송 코드가 0 이었다(셀프 QA I-04, 2026-09-12).
-- 방문자가 연락처 폼에 이메일을 남겼으면 운영자 답장·되돌림 때 메일 1통을 보낸다.
-- 세 컬럼 전부 NULL 허용 — 이메일을 안 남긴 대화의 응답은 아무것도 안 찍힌다.

ALTER TABLE responses ADD COLUMN IF NOT EXISTS email_sent_at TIMESTAMPTZ;      -- 발송 성공 시각
ALTER TABLE responses ADD COLUMN IF NOT EXISTS email_message_id TEXT;          -- Postmark MessageID
ALTER TABLE responses ADD COLUMN IF NOT EXISTS email_error TEXT;               -- 마지막 실패 사유(성공하면 NULL)


-- ═══════════════════════════ 20260913_01_insight_source_messages.sql ═══════════════════════════

-- I-05 즉답 맥락 — 보충 턴이 기존 인사이트를 갱신할 때 어느 메시지가 보태졌는지 남긴다.
--
-- `message_id` 는 첫 제보 메시지 그대로(UNIQUE 유지). 보충 턴은 `source_message_ids` 에 쌓인다.
-- 배치 분류(`api/classify`)는 이 배열까지 보고 "이미 분류됨"을 판정한다 — 안 그러면
-- [분류] 버튼이 보충 턴을 새 인사이트로 만들어 조각 문제가 뒷문으로 재발한다.
-- PR 엔진은 이 메시지들의 본문을 「(보충)」 으로 덧붙여 읽는다.
--
-- 추가만 한다. 기존 행은 빈 배열·NULL 로 남고 동작이 바뀌지 않는다.
ALTER TABLE insights ADD COLUMN IF NOT EXISTS source_message_ids UUID[] NOT NULL DEFAULT '{}';
ALTER TABLE insights ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ;
CREATE INDEX IF NOT EXISTS idx_ins_source_messages ON insights USING GIN (source_message_ids);


-- ═══════════════════════════ 20260913_02_extend_insight_fn.sql ═══════════════════════════

-- I-05 보충 턴 갱신을 «DB 함수 하나»로 좁힌다.
--
-- 왜 애플리케이션 UPDATE 로는 부족한가 — 갱신 여부를 읽고(후보 조회) 쓰기까지 최대 10초가
-- 비어 있다(LLM 호출). 그 사이에 운영자가 [지금 묶기]·[PR 만들기] 를 누를 수 있고, 같은
-- 대화의 두 요청이 동시에 같은 인사이트를 갱신할 수도 있다. 조건을 UPDATE 문 «안»에 두면
-- 판정과 쓰기가 한 문장에서 원자적으로 일어나고, 못 쓰는 경우는 0행으로 돌아온다.
--
-- 각 조건이 있는 이유:
--   bot_id      = p_bot_id     다른 테넌트의 인사이트를 id 하나로 갱신할 수 없게. 애플리케이션이
--                              service_role 로 붙으므로 RLS 가 막아 주지 않는다.
--   group_id is null           이미 묶인 제보의 근거가 사람 몰래 바뀌면 안 된다. 그 묶음으로
--                              스펙 초안이 나갔거나 PR 이 떴을 수 있다.
--   not exists (auto_dev_runs) 이 인사이트로 PR 을 이미 만들었으면 마찬가지다. 리뷰어가 본
--                              근거와 DB 의 근거가 달라지는 것이 가장 나쁘다.
--   cardinality < 50           보충 턴 배열의 상한. 무인증 위젯이라 한 대화에 수천 턴을 쏟아부어
--                              한 행을 무한정 키우는 경로를 막는다. 넘치면 새 행으로 떨어진다.
--   p_message_id = any(...)    같은 메시지를 두 번 더하지 않는다(재시도·지연 경로 대비).
--
-- 0행이면 NULL 을 돌려준다. 호출부(applyInsightWrite)는 그때 새 인사이트로 떨어져
-- **제보를 잃지 않는다** — 이 함수는 「합칠 수 있으면 합쳐라」이지 「합쳐야 한다」가 아니다.

CREATE OR REPLACE FUNCTION public.extend_insight(
  p_bot_id     uuid,
  p_id         uuid,
  p_message_id uuid,
  p_category   text,
  p_summary    text,
  p_sentiment  text,
  p_follow_up  boolean
) RETURNS uuid
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE insights
  SET
    category = p_category,
    summary = p_summary,
    sentiment = p_sentiment,
    follow_up_needed = p_follow_up,
    updated_at = now(),
    source_message_ids = CASE
      WHEN p_message_id IS NULL THEN source_message_ids
      WHEN p_message_id = ANY(source_message_ids) THEN source_message_ids
      ELSE array_append(source_message_ids, p_message_id)
    END
  WHERE id = p_id
    AND bot_id = p_bot_id
    AND group_id IS NULL
    AND cardinality(source_message_ids) < 50
    AND NOT EXISTS (
      SELECT 1 FROM auto_dev_runs r WHERE r.insight_id = p_id
    )
  RETURNING id;
$$;

-- ⚠️ Supabase 는 새 함수에 anon·authenticated EXECUTE 를 «기본으로» 부여한다.
-- `REVOKE ... FROM PUBLIC` 만으로는 그 둘이 안 좁혀진다 — 셋을 모두 회수해야
-- service_role 만 남는다(bump_bot_usage 때 실측한 것과 같은 함정).
REVOKE ALL ON FUNCTION public.extend_insight(uuid, uuid, uuid, text, text, text, boolean)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.extend_insight(uuid, uuid, uuid, text, text, text, boolean)
  TO service_role;


-- ═══════════════════════════ 20260913_03_handoff.sql ═══════════════════════════

-- 「상담원 연결」(백로그 B2 v2, 2026-09-13)
--
-- messages.handoff_at      — 방문자가 「상담원 연결」로 남긴 메시지. AI 가 답하지 않고 사람에게 간다.
-- conversations.owner_notified_at — 봇 소유자에게 상담원 연결 알림 메일을 마지막으로 보낸 시각(같은 대화 1시간 1통).
-- 전부 추가만. 기존 행은 NULL 이라 동작이 바뀌지 않는다.

alter table public.messages add column if not exists handoff_at timestamptz;
alter table public.conversations add column if not exists owner_notified_at timestamptz;


-- ═══════════════════════════ 20260913_04_run_explanation.sql ═══════════════════════════

-- 수정안의 「담당자용 설명」 (2026-09-13, I-19).
--
-- 「수정 PR」 상세에서 비개발자 담당자가 반영 여부를 정하려면 diff 가 아니라
-- 「무엇이 문제였고 / 무엇을 바꿨고 / 반영되면 어떻게 되는지 / 확인하지 못한 것」이 필요하다.
-- 엔진이 2-pass 에서 수정안과 함께 쓰고, 형태는 src/lib/auto-dev/explanation.ts 가 정한다:
--   { problem, change, effect, unverified: [{ text, verifiableBy, files, question, verdict }], source }
-- [AI 에게 확인시키기] 결과(verdict)도 같은 JSON 안에 쓴다 — 항목이 곧 손잡이라 따로 둘 이유가 없다.
--
-- 컬럼 추가만. 기존 실행은 NULL 이고, 화면은 그때 PR 본문에서 최선의 설명을 뽑아 보여준다(source='pr_body').

ALTER TABLE auto_dev_runs
  ADD COLUMN IF NOT EXISTS explanation JSONB;

COMMENT ON COLUMN auto_dev_runs.explanation IS
  '담당자용 설명 {problem, change, effect, unverified[], source}. 엔진이 쓰고 verify 라우트가 verdict 를 채운다. NULL = 이 기능 전 실행';


-- ═══════════════════════════ 20260913_05_github_token.sql ═══════════════════════════

-- B5 GitHub 연결 BYO — 봇별 GitHub 토큰 (2026-09-13).
--
-- 왜: PR 엔진·PR 검토 화면이 플랫폼 공용 GITHUB_TOKEN 하나로 GitHub 을 부른다.
-- 우리가 초대받지 않은 레포엔 push 권한이 없어, 운영자가 자기 레포를 등록하면 「PR 만들기」가 실패한다.
-- 봇에 토큰이 있으면 그걸 먼저 쓰고, 없으면 종전대로 공용 토큰으로 간다 — 기존 봇 동작 불변.
--
-- 구조는 LLM 키 BYOK(20260910_01·_02)와 같다: AES-256-GCM 암호문 + 마지막 4자 + 검증 시각 + 실패 시각/사유.
-- 원문은 어떤 응답에도 나가지 않는다. 화면은 last4 만 읽는다(암호문 컬럼은 select 에 넣지 않을 것).
-- failed_reason 에는 lib/github/token.ts 의 3분류 «고정 문자열»만 들어간다 — GitHub 에러 원문 금지.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_encrypted   TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_last4       TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_verified_at TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_failed_at   TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_failed_reason TEXT;


-- ═══════════════════════════ 20260913_06_github_token_broad.sql ═══════════════════════════

-- B5 후속(보안 재검토 R2) — 저장된 GitHub 토큰이 «계정 전체 레포»에 닿는 종류(classic PAT·OAuth)인지.
-- 저장 때 x-oauth-scopes 헤더 유무로 정한다(fine-grained 는 헤더가 없다). 스코프 문자열은 저장하지 않는다 —
-- 비밀은 아니지만 boolean 이상의 쓸모가 없다. 사고 때 「어느 봇이 계정 전체 자격을 들고 있나」에 답하는 컬럼.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_token_broad BOOLEAN NOT NULL DEFAULT false;


-- ═══════════════════════════ 20260913_07_github_app.sql ═══════════════════════════

-- GitHub App 설치형 연결 (2026-09-13, 안 B). 봇마다 «우리 앱이 설치된 installation» 을 기억한다.
--
-- 왜: 봇별 PAT(20260913_05)는 운영자가 GitHub 설정 화면에서 토큰을 손수 만들어 붙여 넣어야 한다.
-- 조사한 12개 서비스(Vercel·Netlify·Sentry·Devin·Cursor·Codegen·Gleap·Copilot …) 중 PAT 를 받는 곳은 0 이고
-- 레포에 쓰는 곳은 전부 GitHub App 설치다 — 「설치」 버튼 → GitHub 화면에서 레포 선택 → 끝.
-- 설치 토큰은 1시간마다 자동 발급되므로 여기엔 **비밀이 없다.** 설치 id 와 계정 이름뿐이다.
--
-- 판정은 installation_id 쿼리 파라미터가 아니라 «봇 레포로 GET /repos/{o}/{r}/installation» 으로 한다
-- (공식 문서: installation_id 는 스푸핑 가능). 잃어버림(lost_*)은 웹훅(installation.deleted/suspend,
-- installation_repositories.removed)이 적는다. 우선순위: 설치 → 봇 PAT → 공용 토큰. 기존 봇은 NULL 이라 무변화.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_id           BIGINT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_login        TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_connected_at TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_lost_at      TIMESTAMPTZ;
-- 고정 문자열만: uninstalled · suspended · repo_removed · missing (lib/github/app.ts InstallationLostReason)
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_lost_reason  TEXT;
-- 웹훅이 installation id 로 봇을 찾는다
CREATE INDEX IF NOT EXISTS idx_bots_github_installation
  ON bots (github_installation_id) WHERE github_installation_id IS NOT NULL;
-- 누구의 인가로 묶였나(설치 콜백에서 유저 토큰으로 확인한 GitHub 로그인). 비밀 아님, 감사용
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_by TEXT;
-- 설치가 「All repositories」인가(보안 재검토 M3). 우리가 쓰는 건 이 봇의 레포 하나지만,
-- 운영자가 계정 전체를 내준 상태라는 사실은 화면이 말해야 한다. 값은 'all' | 'selected' 만.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS github_installation_repo_selection TEXT;


-- ═══════════════════════════ 20260913_10_pipeline_intake.sql ═══════════════════════════

-- Durable intake and per-bot atomic grouping. Local migration; service-role RPCs only.
ALTER TABLE messages ADD COLUMN IF NOT EXISTS classification_state text NOT NULL DEFAULT 'pending'
  CHECK (classification_state IN ('pending','processing','failed','done','exhausted'));
ALTER TABLE messages ADD COLUMN IF NOT EXISTS classification_attempts integer NOT NULL DEFAULT 0;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS classification_next_at timestamptz NOT NULL DEFAULT (now() + interval '90 seconds');
ALTER TABLE messages ADD COLUMN IF NOT EXISTS classification_lease uuid;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS classification_error text;
CREATE INDEX IF NOT EXISTS messages_classification_queue ON messages (classification_next_at, detected_at, id)
  WHERE classification_state IN ('pending','failed','processing');
CREATE TABLE IF NOT EXISTS insight_message_sources (
  message_id uuid PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,
  insight_id uuid NOT NULL REFERENCES insights(id) ON DELETE CASCADE,
  bot_id uuid NOT NULL REFERENCES bots(id) ON DELETE CASCADE
);
ALTER TABLE insight_message_sources ENABLE ROW LEVEL SECURITY;
-- Deliberately fail on historical conflicting membership; never erase customer evidence.
INSERT INTO insight_message_sources(message_id, insight_id, bot_id)
SELECT DISTINCT x.message_id, i.id, i.bot_id FROM insights i
CROSS JOIN LATERAL unnest(array_append(i.source_message_ids, i.message_id)) x(message_id)
WHERE x.message_id IS NOT NULL
ON CONFLICT (message_id) DO UPDATE SET insight_id = CASE
  WHEN insight_message_sources.insight_id = excluded.insight_id THEN excluded.insight_id ELSE NULL END;
UPDATE messages m SET classification_state='done', classification_next_at=now()
WHERE EXISTS (SELECT 1 FROM insight_message_sources s WHERE s.message_id=m.id);

CREATE OR REPLACE FUNCTION pipeline_source_membership() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$
DECLARE mid uuid;
BEGIN
  FOR mid IN SELECT DISTINCT x FROM unnest(array_append(NEW.source_message_ids,NEW.message_id)) x WHERE x IS NOT NULL ORDER BY x LOOP
    IF NOT EXISTS (SELECT 1 FROM messages WHERE id=mid AND bot_id=NEW.bot_id) THEN RAISE EXCEPTION 'source_bot_mismatch'; END IF;
    INSERT INTO insight_message_sources(message_id,insight_id,bot_id) VALUES(mid,NEW.id,NEW.bot_id)
      ON CONFLICT(message_id) DO UPDATE SET insight_id = CASE WHEN insight_message_sources.insight_id=excluded.insight_id THEN excluded.insight_id ELSE NULL END;
  END LOOP;
  RETURN NEW;
END $$;
CREATE TRIGGER pipeline_sources AFTER INSERT OR UPDATE OF message_id, source_message_ids ON insights
FOR EACH ROW EXECUTE FUNCTION pipeline_source_membership();

CREATE OR REPLACE FUNCTION pipeline_settle_insight(p_bot_id uuid,p_message_id uuid,p_insight jsonb,p_extend_id uuid DEFAULT NULL,p_lease uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE m messages; iid uuid; existing_id uuid;
BEGIN
 SELECT * INTO m FROM messages WHERE id=p_message_id AND bot_id=p_bot_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'message_not_saved'; END IF;
 IF p_lease IS NOT NULL AND (m.classification_lease IS DISTINCT FROM p_lease OR m.classification_state <> 'processing') THEN RAISE EXCEPTION 'stale_classification_lease'; END IF;
 SELECT insight_id INTO existing_id FROM insight_message_sources WHERE message_id=p_message_id;
 IF existing_id IS NOT NULL THEN
   UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
   RETURN jsonb_build_object('id',existing_id,'created',false);
 END IF;
 IF p_insight IS NOT NULL AND p_insight <> 'null'::jsonb THEN
   IF p_extend_id IS NOT NULL THEN
     -- Existing implementation protects published/grouped evidence. A blocked extension becomes a new report for grouping.
     SELECT extend_insight(p_bot_id,p_extend_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false)) INTO iid;
   END IF;
   IF iid IS NULL THEN
     INSERT INTO insights(bot_id,message_id,category,summary,sentiment,follow_up_needed)
     VALUES(p_bot_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false)) RETURNING id INTO iid;
   END IF;
 END IF;
 UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
 RETURN jsonb_build_object('id',iid,'created',iid IS NOT NULL AND p_extend_id IS DISTINCT FROM iid);
END $$;

CREATE OR REPLACE FUNCTION pipeline_claim_message(p_bot_ids uuid[])
RETURNS SETOF messages LANGUAGE plpgsql SET search_path=public AS $$
DECLARE chosen uuid;
BEGIN
 -- Serialize the short selection transaction: only one in-flight message per conversation.
 PERFORM pg_advisory_xact_lock(hashtextextended('pipeline-classification-claim',0));
 UPDATE messages SET classification_state='exhausted',classification_error='retry_limit',classification_lease=NULL
 WHERE bot_id=ANY(p_bot_ids) AND classification_state IN ('failed','processing') AND classification_attempts>=3 AND classification_next_at<=now();
 SELECT m.id INTO chosen FROM messages m WHERE m.bot_id=ANY(p_bot_ids)
 AND m.classification_state IN ('pending','failed','processing') AND m.classification_next_at<=now() AND m.classification_attempts<3
 AND NOT EXISTS (SELECT 1 FROM messages busy WHERE busy.conversation_id=m.conversation_id AND busy.id<>m.id
    AND busy.classification_state='processing' AND busy.classification_next_at>now())
 ORDER BY m.detected_at,m.id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF chosen IS NULL THEN RETURN; END IF;
 RETURN QUERY UPDATE messages SET classification_state='processing',classification_attempts=classification_attempts+1,
 classification_lease=gen_random_uuid(),classification_next_at=now()+interval '90 seconds',classification_error=NULL
 WHERE id=chosen RETURNING *;
END $$;

CREATE OR REPLACE FUNCTION pipeline_fail_message(p_bot_id uuid,p_message_id uuid,p_lease uuid,p_reason text)
RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
 UPDATE messages SET classification_state=CASE WHEN classification_attempts>=3 THEN 'exhausted' ELSE 'failed' END,
 classification_error=left(p_reason,120),classification_next_at=now()+make_interval(secs=>30*power(2,classification_attempts)::integer),classification_lease=NULL
 WHERE id=p_message_id AND bot_id=p_bot_id AND classification_state='processing' AND classification_lease=p_lease;
 RETURN FOUND;
END $$;

ALTER TABLE insight_groups ADD COLUMN IF NOT EXISTS follow_up_pending boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS grouping_revisions(bot_id uuid PRIMARY KEY REFERENCES bots(id) ON DELETE CASCADE, revision bigint NOT NULL DEFAULT 0);
ALTER TABLE grouping_revisions ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION pipeline_group_snapshot(p_bot_id uuid,p_limit integer DEFAULT 40)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE rev bigint; existing jsonb; candidates jsonb; pending integer;
BEGIN
 INSERT INTO grouping_revisions(bot_id) VALUES(p_bot_id) ON CONFLICT DO NOTHING;
 SELECT revision INTO rev FROM grouping_revisions WHERE bot_id=p_bot_id FOR UPDATE;
 IF (SELECT count(*) FROM insight_groups WHERE bot_id=p_bot_id)>500 THEN RAISE EXCEPTION 'grouping_capacity_requires_partition'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(g)),'[]') INTO existing FROM (SELECT id,title,summary,category,status FROM insight_groups WHERE bot_id=p_bot_id ORDER BY created_at,id) g;
 SELECT count(*) INTO pending FROM insights WHERE bot_id=p_bot_id AND group_id IS NULL AND category IN ('bug','ux','feature_request');
 SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]') INTO candidates FROM (SELECT id,category,summary FROM insights WHERE bot_id=p_bot_id AND group_id IS NULL AND category IN ('bug','ux','feature_request') ORDER BY created_at,id LIMIT least(greatest(p_limit,1),40)) i;
 RETURN jsonb_build_object('revision',rev,'existing',existing,'insights',candidates,'pending',pending);
END $$;

CREATE OR REPLACE FUNCTION pipeline_commit_groups(p_bot_id uuid,p_revision bigint,p_groups jsonb)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE rev bigint; g jsonb; gid uuid; ids uuid[]; linked integer; total integer:=0; receipts jsonb:='[]'; title_text text; target_category text;
BEGIN
 SELECT revision INTO rev FROM grouping_revisions WHERE bot_id=p_bot_id FOR UPDATE;
 IF NOT FOUND OR rev<>p_revision THEN RAISE EXCEPTION 'stale_group_snapshot'; END IF;
 IF jsonb_typeof(p_groups)<>'array' THEN RAISE EXCEPTION 'invalid_groups'; END IF;
 FOR g IN SELECT value FROM jsonb_array_elements(p_groups) LOOP
   IF g->>'category' NOT IN ('bug','ux','feature_request') OR length(trim(coalesce(g->>'title','')))=0 THEN RAISE EXCEPTION 'invalid_group'; END IF;
   SELECT array_agg(DISTINCT value::uuid) INTO ids FROM jsonb_array_elements_text(g->'insight_ids');
   IF coalesce(cardinality(ids),0)=0 THEN RAISE EXCEPTION 'empty_group'; END IF;
   -- Locks prevent a concurrent extension changing category/evidence during linking.
   PERFORM id FROM insights WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
   IF (SELECT count(*) FROM insights WHERE id=ANY(ids) AND bot_id=p_bot_id AND group_id IS NULL AND category IN ('bug','ux','feature_request')
       AND (category='feature_request')=((g->>'category')='feature_request')) <> cardinality(ids) THEN RAISE EXCEPTION 'invalid_or_stale_members'; END IF;
   gid:=NULL; target_category:=NULL;
   IF coalesce(g->>'existing_group_id','')<>'' THEN
     SELECT id,title,category INTO gid,title_text,target_category FROM insight_groups WHERE id=(g->>'existing_group_id')::uuid AND bot_id=p_bot_id FOR UPDATE;
     IF gid IS NULL OR (target_category='feature_request')<>((g->>'category')='feature_request') THEN RAISE EXCEPTION 'invalid_existing_group'; END IF;
     UPDATE insight_groups SET follow_up_pending=true WHERE id=gid AND status<>'open';
   ELSE
     INSERT INTO insight_groups(bot_id,title,summary,category) VALUES(p_bot_id,g->>'title',g->>'summary',g->>'category') RETURNING id,title INTO gid,title_text;
   END IF;
   UPDATE insights SET group_id=gid WHERE id=ANY(ids) AND bot_id=p_bot_id AND group_id IS NULL;
   GET DIAGNOSTICS linked=ROW_COUNT;
   IF linked<>cardinality(ids) THEN RAISE EXCEPTION 'partial_group_write'; END IF;
   total:=total+linked;
   receipts:=receipts||jsonb_build_array(jsonb_build_object('id',gid,'title',title_text,'count',linked));
 END LOOP;
 UPDATE grouping_revisions SET revision=revision+1 WHERE bot_id=p_bot_id;
 RETURN jsonb_build_object('grouped',total,'groups',receipts);
END $$;

REVOKE ALL ON FUNCTION pipeline_source_membership(),pipeline_settle_insight(uuid,uuid,jsonb,uuid,uuid),pipeline_claim_message(uuid[]),pipeline_fail_message(uuid,uuid,uuid,text),pipeline_group_snapshot(uuid,integer),pipeline_commit_groups(uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION pipeline_settle_insight(uuid,uuid,jsonb,uuid,uuid),pipeline_claim_message(uuid[]),pipeline_fail_message(uuid,uuid,uuid,text),pipeline_group_snapshot(uuid,integer),pipeline_commit_groups(uuid,bigint,jsonb) TO service_role;

-- Long-running local/hosted PostgREST needs the new RPC signatures immediately.
NOTIFY pgrst, 'reload schema';


-- ═══════════════════════════ 20260913_11_pipeline_lifecycle.sql ═══════════════════════════

-- Preserve historical completed rows: unknown execution proof is never validated.
ALTER TABLE auto_dev_runs
 ADD COLUMN IF NOT EXISTS validation_status text NOT NULL DEFAULT 'unknown',
 ADD COLUMN IF NOT EXISTS validation_evidence jsonb,
 ADD COLUMN IF NOT EXISTS publication_intent jsonb,
 ADD COLUMN IF NOT EXISTS publication_status text NOT NULL DEFAULT 'none',
 ADD COLUMN IF NOT EXISTS stop_reason text,
 ADD COLUMN IF NOT EXISTS lease_until timestamptz,
 ADD COLUMN IF NOT EXISTS lease_token uuid,
 ADD COLUMN IF NOT EXISTS deployment_status text NOT NULL DEFAULT 'unknown',
 ADD COLUMN IF NOT EXISTS deployment_reason text,
 ADD COLUMN IF NOT EXISTS merge_commit_sha text,
 ADD COLUMN IF NOT EXISTS follow_up_checked_at timestamptz,
 ADD COLUMN IF NOT EXISTS follow_up_error text,
 ADD COLUMN IF NOT EXISTS generation_budget jsonb;
CREATE TABLE IF NOT EXISTS auto_dev_attempts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES auto_dev_runs(id) ON DELETE CASCADE,
 attempt integer NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,attempt)
);
ALTER TABLE auto_dev_attempts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS attempts_owner ON auto_dev_attempts;
CREATE POLICY attempts_owner ON auto_dev_attempts FOR SELECT USING (EXISTS (SELECT 1 FROM auto_dev_runs r JOIN bots b ON b.id=r.bot_id WHERE r.id=run_id AND b.user_id=auth.uid()));
-- Advisory locks serialize even legacy duplicate targets without deleting historical records.
CREATE OR REPLACE FUNCTION create_pipeline_run(p_bot_id uuid,p_group_id uuid DEFAULT NULL,p_insight_id uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE g insight_groups; i insights; result uuid;
BEGIN
 IF (p_group_id IS NULL)=(p_insight_id IS NULL) THEN RAISE EXCEPTION 'exactly one target required'; END IF;
 IF p_insight_id IS NOT NULL THEN
  SELECT * INTO STRICT i FROM insights WHERE id=p_insight_id AND bot_id=p_bot_id;
  p_group_id:=i.group_id;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_bot_id::text||':'||coalesce(p_group_id,p_insight_id)::text,0));
 IF p_group_id IS NOT NULL THEN
  SELECT * INTO STRICT g FROM insight_groups WHERE id=p_group_id AND bot_id=p_bot_id FOR UPDATE;
  IF g.status<>'open' OR g.follow_up_pending THEN RAISE EXCEPTION 'group_follow_up_hold'; END IF;
  IF g.category NOT IN ('bug','ux') THEN RAISE EXCEPTION 'category_not_fixable'; END IF;
  p_insight_id:=NULL;
 ELSIF i.category NOT IN ('bug','ux') THEN RAISE EXCEPTION 'category_not_fixable'; END IF;
 SELECT id INTO result FROM auto_dev_runs WHERE bot_id=p_bot_id
 AND ((p_group_id IS NOT NULL AND (group_id=p_group_id OR (group_id IS NULL AND insight_id IN (SELECT id FROM insights WHERE group_id=p_group_id)))) OR (p_group_id IS NULL AND insight_id=p_insight_id))
 AND (status IN ('running','in_progress') OR publication_status='pending' OR (pr_url IS NOT NULL AND closed_at IS NULL))
 ORDER BY created_at LIMIT 1;
 IF result IS NOT NULL THEN
  IF p_group_id IS NOT NULL THEN UPDATE auto_dev_runs SET group_id=p_group_id WHERE id=result AND group_id IS NULL; END IF;
  RETURN result;
 END IF;
 INSERT INTO auto_dev_runs(bot_id,group_id,insight_id,status) VALUES(p_bot_id,p_group_id,p_insight_id,'running') RETURNING id INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION create_pipeline_run(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_pipeline_run(uuid,uuid,uuid) TO service_role;
ALTER TABLE responses ADD COLUMN IF NOT EXISTS email_delivery_status text NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS email_attempted_at timestamptz;
UPDATE responses SET email_delivery_status='sent' WHERE email_sent_at IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS responses_loop_closed_once ON responses(auto_dev_run_id,conversation_id);
CREATE OR REPLACE FUNCTION claim_response_email(p_id uuid,p_bot_id uuid,p_conversation_id uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE claimed uuid;
BEGIN
 -- A dead worker could already have sent. Never reset uncertain delivery to pending.
 UPDATE responses SET email_delivery_status='delivery_unknown',email_error='Dispatch interrupted; reconcile provider before retry'
 WHERE id=p_id AND email_delivery_status='dispatching' AND email_attempted_at<now()-interval '1 minute';
 UPDATE responses SET email_delivery_status='dispatching',email_attempted_at=now()
 WHERE id=p_id AND bot_id=p_bot_id AND conversation_id=p_conversation_id AND email_sent_at IS NULL AND email_delivery_status IN ('pending','failed') RETURNING id INTO claimed;
 RETURN claimed IS NOT NULL;
END $$;
REVOKE ALL ON FUNCTION claim_response_email(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION claim_response_email(uuid,uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION claim_pipeline_run(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE result uuid;
BEGIN
 UPDATE auto_dev_runs SET status='in_progress',lease_until=now()+interval '240 seconds',lease_token=gen_random_uuid()
 WHERE id=p_id AND (status='running' OR (status='in_progress' AND lease_until<now()) OR (status='failed' AND publication_status='pending'))
 RETURNING id INTO result;
 RETURN result IS NOT NULL;
END $$;
REVOKE ALL ON FUNCTION claim_pipeline_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION claim_pipeline_run(uuid) TO service_role;

CREATE UNIQUE INDEX IF NOT EXISTS auto_dev_active_group ON auto_dev_runs(group_id) WHERE group_id IS NOT NULL AND status IN ('running','in_progress');
CREATE UNIQUE INDEX IF NOT EXISTS auto_dev_active_insight ON auto_dev_runs(insight_id) WHERE group_id IS NULL AND insight_id IS NOT NULL AND status IN ('running','in_progress');
CREATE OR REPLACE FUNCTION complete_pipeline_run(p_id uuid,p_token uuid,p_result jsonb,p_duration integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r auto_dev_runs;
BEGIN
 SELECT * INTO STRICT r FROM auto_dev_runs WHERE id=p_id FOR UPDATE;
 IF r.status<>'in_progress' OR r.lease_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 IF r.validation_status<>'validated' OR r.publication_status<>'pending'
 OR NOT coalesce(r.validation_evidence @> '{"status":"validated"}'::jsonb,false)
 OR NOT coalesce((r.validation_evidence->>'patchDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'profileDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'baseSha') ~ '^[a-f0-9]{40}$',false)
 OR r.validation_evidence->>'patchDigest' IS DISTINCT FROM r.publication_intent->>'patchDigest'
 OR r.validation_evidence->>'profileDigest' IS DISTINCT FROM r.publication_intent->>'profileDigest'
 OR r.validation_evidence->>'baseSha' IS DISTINCT FROM r.publication_intent->>'baseSha'
 OR r.validation_evidence->>'runId' IS DISTINCT FROM p_id::text
 OR p_result->>'pr_url' IS NULL THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 UPDATE auto_dev_runs SET status='completed',publication_status='published',pr_url=p_result->>'pr_url',pr_number=(p_result->>'pr_number')::integer,
 files_changed=p_result->'files_changed',duration_ms=p_duration,error_message=NULL,stop_reason=NULL WHERE id=p_id;
 IF r.group_id IS NOT NULL THEN UPDATE insight_groups SET status='pr_created' WHERE id=r.group_id AND status='open'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) TO service_role;
CREATE OR REPLACE FUNCTION record_pipeline_attempt(p_id uuid,p_token uuid,p_evidence jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE next_attempt integer;
BEGIN
 PERFORM id FROM auto_dev_runs WHERE id=p_id AND lease_token=p_token AND status='in_progress' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 SELECT coalesce(max(attempt),0)+1 INTO next_attempt FROM auto_dev_attempts WHERE run_id=p_id;
 INSERT INTO auto_dev_attempts(run_id,attempt,evidence) VALUES(p_id,next_attempt,p_evidence);
 UPDATE auto_dev_runs SET validation_status=p_evidence->>'status',validation_evidence=p_evidence WHERE id=p_id;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION record_pipeline_attempt(uuid,uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION record_pipeline_attempt(uuid,uuid,jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═══════════════════════════ 20260913_12_pipeline_recovery.sql ═══════════════════════════

-- Only an authenticated operator request can start a fresh exhausted recovery cycle.
CREATE TABLE IF NOT EXISTS classification_recovery_cycles (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
 bot_id uuid NOT NULL REFERENCES bots(id) ON DELETE CASCADE, operator_id uuid NOT NULL,
 previous_attempts integer NOT NULL, previous_error text, created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE classification_recovery_cycles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION retry_exhausted_classification(p_message_id uuid,p_operator_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE m messages;
BEGIN
 SELECT msg.* INTO m FROM messages msg JOIN bots b ON b.id=msg.bot_id
 WHERE msg.id=p_message_id AND b.user_id=p_operator_id FOR UPDATE OF msg;
 IF NOT FOUND OR m.classification_state<>'exhausted' THEN RETURN false; END IF;
 INSERT INTO classification_recovery_cycles(message_id,bot_id,operator_id,previous_attempts,previous_error)
 VALUES(m.id,m.bot_id,p_operator_id,m.classification_attempts,m.classification_error);
 UPDATE messages SET classification_state='pending',classification_attempts=0,classification_next_at=now(),classification_lease=NULL,classification_error=NULL WHERE id=m.id;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION retry_exhausted_classification(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION retry_exhausted_classification(uuid,uuid) TO service_role;


-- ═══════════════════════════ 20260913_14_pipeline_source_context.sql ═══════════════════════════

-- Preserve source-only supplements without inventing a classification. Historical hints remain unknown.
ALTER TABLE messages ADD COLUMN IF NOT EXISTS widget_hint text CHECK(widget_hint IN ('bug','feature','question'));

CREATE OR REPLACE FUNCTION pipeline_settle_insight(p_bot_id uuid,p_message_id uuid,p_insight jsonb,p_extend_id uuid DEFAULT NULL,p_lease uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE m messages; iid uuid; existing_id uuid; target insights; original_conversation uuid;
BEGIN
 SELECT * INTO m FROM messages WHERE id=p_message_id AND bot_id=p_bot_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'message_not_saved'; END IF;
 IF p_lease IS NOT NULL AND (m.classification_lease IS DISTINCT FROM p_lease OR m.classification_state <> 'processing') THEN RAISE EXCEPTION 'stale_classification_lease'; END IF;
 SELECT insight_id INTO existing_id FROM insight_message_sources WHERE message_id=p_message_id;
 IF existing_id IS NOT NULL THEN
   UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
   RETURN jsonb_build_object('id',existing_id,'created',false);
 END IF;
 -- Null classification with a known extension is provenance, not permission to rewrite metadata.
 IF p_extend_id IS NOT NULL AND (p_insight IS NULL OR p_insight = 'null'::jsonb) THEN
   -- Same target lock as create_pipeline_run; grouped evidence is also protected by the row lock.
   PERFORM pg_advisory_xact_lock(hashtextextended(p_bot_id::text||':'||p_extend_id::text,0));
   SELECT * INTO target FROM insights WHERE id=p_extend_id AND bot_id=p_bot_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'source_extension_unavailable'; END IF;
   SELECT conversation_id INTO original_conversation FROM messages WHERE id=target.message_id AND bot_id=p_bot_id;
   IF m.conversation_id IS NULL OR original_conversation IS DISTINCT FROM m.conversation_id
     OR target.group_id IS NOT NULL OR coalesce(cardinality(target.source_message_ids),0)>=50
     OR EXISTS(SELECT 1 FROM auto_dev_runs WHERE insight_id=p_extend_id)
   THEN RAISE EXCEPTION 'source_extension_unavailable'; END IF;
   UPDATE insights SET source_message_ids=array_append(coalesce(source_message_ids,ARRAY[]::uuid[]),p_message_id)
     WHERE id=p_extend_id RETURNING id INTO iid;
 ELSIF p_insight IS NOT NULL AND p_insight <> 'null'::jsonb THEN
   IF p_extend_id IS NOT NULL THEN
     -- Existing implementation protects published/grouped evidence. A blocked extension becomes a new report for grouping.
     SELECT extend_insight(p_bot_id,p_extend_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false)) INTO iid;
   END IF;
   IF iid IS NULL THEN
     INSERT INTO insights(bot_id,message_id,category,summary,sentiment,follow_up_needed)
     VALUES(p_bot_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false)) RETURNING id INTO iid;
   END IF;
 END IF;
 UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
 RETURN jsonb_build_object('id',iid,'created',iid IS NOT NULL AND p_extend_id IS DISTINCT FROM iid);
END $$;


-- ═══════════════════════════ 20260913_21_handoff_delivery.sql ═══════════════════════════

-- Durable owner-email dispatch intent; Postmark has no idempotency key.
create table public.handoff_email_deliveries (
  id uuid primary key default gen_random_uuid(),
  bot_id uuid not null references public.bots(id) on delete cascade,
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  claimed_at timestamptz not null default now(),
  status text not null default 'delivery_unknown' check (status in ('delivery_unknown','sent','failed')),
  provider_message_id text,
  error text
);
create index on public.handoff_email_deliveries(bot_id, claimed_at);
alter table public.handoff_email_deliveries enable row level security;
grant all on public.handoff_email_deliveries to service_role;

create function public.claim_handoff_email(p_bot_id uuid,p_conversation_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare claim_id uuid;
begin
  -- Serialize the hourly cap across all conversations belonging to this bot.
  perform 1 from public.bots where id=p_bot_id for update;
  if not found then return jsonb_build_object('reason','lookup_failed'); end if;
  perform 1 from public.conversations where id=p_conversation_id and bot_id=p_bot_id for update;
  if not found then return jsonb_build_object('reason','lookup_failed'); end if;
  if exists(select 1 from public.handoff_email_deliveries where conversation_id=p_conversation_id and status='delivery_unknown') then
    return jsonb_build_object('reason','delivery_unknown');
  end if;
  if exists(select 1 from public.conversations where id=p_conversation_id and owner_notified_at > now()-interval '1 hour') then
    return jsonb_build_object('reason','rate_limited');
  end if;
  if (select count(*) from public.handoff_email_deliveries where bot_id=p_bot_id and claimed_at > now()-interval '1 hour')
    + (select count(*) from public.conversations c where c.bot_id=p_bot_id and c.owner_notified_at > now()-interval '1 hour'
       and not exists(select 1 from public.handoff_email_deliveries d where d.conversation_id=c.id and d.claimed_at > now()-interval '1 hour')) >= 10 then
    return jsonb_build_object('reason','bot_rate_limited');
  end if;
  insert into public.handoff_email_deliveries(bot_id,conversation_id) values(p_bot_id,p_conversation_id) returning id into claim_id;
  update public.conversations set owner_notified_at=now() where id=p_conversation_id;
  return jsonb_build_object('id',claim_id);
end $$;
revoke all on function public.claim_handoff_email(uuid,uuid) from public,anon,authenticated;
grant execute on function public.claim_handoff_email(uuid,uuid) to service_role;

alter table public.conversations add column owner_email_status text;
alter table public.conversations add column owner_email_error text;
create function public.record_handoff_email_status() returns trigger language plpgsql security definer set search_path=public as $$
begin
  if not exists(select 1 from public.handoff_email_deliveries where conversation_id=new.conversation_id and claimed_at>new.claimed_at) then
    update public.conversations set owner_email_status=new.status,owner_email_error=new.error where id=new.conversation_id;
  end if;
  return new;
end $$;
revoke all on function public.record_handoff_email_status() from public,anon,authenticated;
create trigger handoff_email_status after insert or update on public.handoff_email_deliveries for each row execute function public.record_handoff_email_status();


-- ═══════════════════════════ 20260913_22_resolution_confirmation.sql ═══════════════════════════

-- Visitor statements are independent of merge/deployment evidence.
CREATE TABLE IF NOT EXISTS response_confirmation_history (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 response_id uuid NOT NULL REFERENCES responses(id) ON DELETE CASCADE,
 confirmation text NOT NULL CHECK (confirmation IN ('fixed','not_fixed')),
 confirmed_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE response_confirmation_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON response_confirmation_history FROM PUBLIC, anon, authenticated;
GRANT ALL ON response_confirmation_history TO service_role;

CREATE OR REPLACE FUNCTION confirm_widget_resolution(p_bot_id uuid, p_visitor_id uuid, p_response_id uuid, p_confirmation text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r responses; run auto_dev_runs; changed_at timestamptz;
BEGIN
 IF p_confirmation IS NOT NULL AND p_confirmation NOT IN ('fixed','not_fixed') THEN RAISE EXCEPTION 'invalid_confirmation'; END IF;
 SELECT response.* INTO r FROM responses response
 JOIN conversations c ON c.id=response.conversation_id AND c.bot_id=response.bot_id
 JOIN bots b ON b.id=response.bot_id
 JOIN auto_dev_runs a ON a.id=response.auto_dev_run_id AND a.bot_id=response.bot_id
 WHERE response.id=p_response_id AND response.bot_id=p_bot_id
 AND c.source='web' AND c.external_user_id=p_visitor_id::text
 AND b.status<>'paused' AND response.response_type='loop_closed'
 AND response.delivered_at IS NOT NULL AND a.merged_at IS NOT NULL
 FOR UPDATE OF response;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_confirmation IS NOT NULL AND r.user_confirmation IS DISTINCT FROM p_confirmation THEN
  changed_at:=clock_timestamp();
  UPDATE responses SET user_confirmation=p_confirmation,user_confirmed_at=changed_at WHERE id=r.id;
  INSERT INTO response_confirmation_history(response_id,confirmation,confirmed_at) VALUES(r.id,p_confirmation,changed_at);
  IF p_confirmation='not_fixed' THEN
   SELECT * INTO run FROM auto_dev_runs WHERE id=r.auto_dev_run_id;
   UPDATE insight_groups SET follow_up_pending=true WHERE bot_id=p_bot_id AND id=coalesce(run.group_id,(SELECT group_id FROM insights WHERE id=run.insight_id AND bot_id=p_bot_id));
   UPDATE conversations SET escalated_at=changed_at WHERE id=r.conversation_id AND bot_id=p_bot_id;
  END IF;
  r.user_confirmation:=p_confirmation; r.user_confirmed_at:=changed_at;
 END IF;
 RETURN jsonb_build_object('responseId',r.id,'confirmation',r.user_confirmation,'confirmedAt',r.user_confirmed_at);
END $$;
REVOKE ALL ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) TO service_role;


-- ═══════════════════════════ 20260913_23_run_claim_token.sql ═══════════════════════════

-- Capture the token in the same statement that acquires the lease.
BEGIN;
DROP FUNCTION claim_pipeline_run(uuid);
CREATE FUNCTION claim_pipeline_run(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE token uuid;
BEGIN
 UPDATE auto_dev_runs SET status='in_progress',lease_until=clock_timestamp()+interval '240 seconds',lease_token=gen_random_uuid()
 WHERE id=p_id AND (status='running' OR (status='in_progress' AND lease_until<clock_timestamp())
 OR (status IN ('failed','stopped','unverifiable') AND publication_status='pending' AND publication_intent IS NOT NULL))
 RETURNING lease_token INTO token;
 RETURN token;
END $$;
REVOKE ALL ON FUNCTION claim_pipeline_run(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION claim_pipeline_run(uuid) TO service_role;
CREATE OR REPLACE FUNCTION assert_pipeline_run_lease(p_id uuid,p_token uuid) RETURNS boolean
LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$
 -- GitHub requests are capped at 30s; do not start one at the lease boundary.
 SELECT EXISTS(SELECT 1 FROM auto_dev_runs WHERE id=p_id AND lease_token=p_token AND status='in_progress' AND lease_until>clock_timestamp()+interval '30 seconds');
$$;
REVOKE ALL ON FUNCTION assert_pipeline_run_lease(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION assert_pipeline_run_lease(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION save_pipeline_run(p_id uuid,p_token uuid,p_values jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r auto_dev_runs;
BEGIN
 SELECT * INTO r FROM auto_dev_runs WHERE id=p_id AND lease_token=p_token AND status='in_progress' AND lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_values) k WHERE k NOT IN ('status','error_message','duration_ms','stop_reason','validation_status','validation_evidence','publication_status','publication_intent','generation_budget')) THEN RAISE EXCEPTION 'invalid_run_patch'; END IF;
 r:=jsonb_populate_record(r,p_values);
 UPDATE auto_dev_runs SET status=r.status,error_message=r.error_message,duration_ms=r.duration_ms,stop_reason=r.stop_reason,
 validation_status=r.validation_status,validation_evidence=r.validation_evidence,publication_status=r.publication_status,
 publication_intent=r.publication_intent,generation_budget=r.generation_budget WHERE id=p_id;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION save_pipeline_run(uuid,uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION save_pipeline_run(uuid,uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION complete_pipeline_run(p_id uuid,p_token uuid,p_result jsonb,p_duration integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r auto_dev_runs;
BEGIN
 SELECT * INTO STRICT r FROM auto_dev_runs WHERE id=p_id FOR UPDATE;
 IF r.status<>'in_progress' OR r.lease_token IS DISTINCT FROM p_token OR r.lease_until IS NULL OR r.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 IF r.validation_status<>'validated' OR r.publication_status<>'pending'
 OR NOT coalesce(r.validation_evidence @> '{"status":"validated"}'::jsonb,false)
 OR NOT coalesce((r.validation_evidence->>'patchDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'profileDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'baseSha') ~ '^[a-f0-9]{40}$',false)
 OR r.validation_evidence->>'patchDigest' IS DISTINCT FROM r.publication_intent->>'patchDigest'
 OR r.validation_evidence->>'profileDigest' IS DISTINCT FROM r.publication_intent->>'profileDigest'
 OR r.validation_evidence->>'baseSha' IS DISTINCT FROM r.publication_intent->>'baseSha'
 OR r.validation_evidence->>'runId' IS DISTINCT FROM p_id::text
 OR p_result->>'pr_url' IS NULL THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 UPDATE auto_dev_runs SET status='completed',publication_status='published',pr_url=p_result->>'pr_url',pr_number=(p_result->>'pr_number')::integer,
 files_changed=p_result->'files_changed',duration_ms=p_duration,error_message=NULL,stop_reason=NULL WHERE id=p_id;
 IF r.group_id IS NOT NULL THEN UPDATE insight_groups SET status='pr_created' WHERE id=r.group_id AND status='open'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) TO service_role;
CREATE OR REPLACE FUNCTION record_pipeline_attempt(p_id uuid,p_token uuid,p_evidence jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE next_attempt integer;
BEGIN
 PERFORM id FROM auto_dev_runs WHERE id=p_id AND lease_token=p_token AND status='in_progress' AND lease_until>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 SELECT coalesce(max(attempt),0)+1 INTO next_attempt FROM auto_dev_attempts WHERE run_id=p_id;
 INSERT INTO auto_dev_attempts(run_id,attempt,evidence) VALUES(p_id,next_attempt,p_evidence);
 UPDATE auto_dev_runs SET validation_status=p_evidence->>'status',validation_evidence=p_evidence WHERE id=p_id;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION record_pipeline_attempt(uuid,uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION record_pipeline_attempt(uuid,uuid,jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';
COMMIT;


-- ═══════════════════════════ 20260913_24_pipeline_explanation.sql ═══════════════════════════

-- Preserve the final-candidate explanation with the lease-bound completion transaction.
CREATE OR REPLACE FUNCTION complete_pipeline_run(p_id uuid,p_token uuid,p_result jsonb,p_duration integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r auto_dev_runs;
BEGIN
 SELECT * INTO STRICT r FROM auto_dev_runs WHERE id=p_id FOR UPDATE;
 IF r.status<>'in_progress' OR r.lease_token IS DISTINCT FROM p_token OR r.lease_until IS NULL OR r.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 IF r.validation_status<>'validated' OR r.publication_status<>'pending'
 OR NOT coalesce(r.validation_evidence @> '{"status":"validated"}'::jsonb,false)
 OR NOT coalesce((r.validation_evidence->>'patchDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'profileDigest') ~ '^[a-f0-9]{64}$',false)
 OR NOT coalesce((r.validation_evidence->>'baseSha') ~ '^[a-f0-9]{40}$',false)
 OR r.validation_evidence->>'patchDigest' IS DISTINCT FROM r.publication_intent->>'patchDigest'
 OR r.validation_evidence->>'profileDigest' IS DISTINCT FROM r.publication_intent->>'profileDigest'
 OR r.validation_evidence->>'baseSha' IS DISTINCT FROM r.publication_intent->>'baseSha'
 OR r.validation_evidence->>'runId' IS DISTINCT FROM p_id::text
 OR p_result->>'pr_url' IS NULL THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 UPDATE auto_dev_runs SET status='completed',publication_status='published',pr_url=p_result->>'pr_url',pr_number=(p_result->>'pr_number')::integer,
 files_changed=p_result->'files_changed',explanation=p_result->'explanation',duration_ms=p_duration,error_message=NULL,stop_reason=NULL WHERE id=p_id;
 IF r.group_id IS NOT NULL THEN UPDATE insight_groups SET status='pr_created' WHERE id=r.group_id AND status='open'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) TO service_role;


-- ═══════════════════════════ 20260913_25_atomic_verdict.sql ═══════════════════════════

-- Advisory opinions only: never updates execution validation or publication state.
CREATE OR REPLACE FUNCTION public.save_run_verdict(p_run_id uuid,p_index integer,p_expected_item jsonb,p_verdict jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE current_explanation jsonb; current_item jsonb;
BEGIN
 SELECT explanation INTO current_explanation FROM auto_dev_runs WHERE id=p_run_id FOR UPDATE;
 IF NOT FOUND OR p_index<0 THEN RETURN NULL; END IF;
 current_item:=current_explanation->'unverified'->p_index;
 IF current_item IS NULL OR (current_item-'verdict') IS DISTINCT FROM (p_expected_item-'verdict')
 OR current_item->>'verdict' IS NOT NULL THEN RETURN NULL; END IF;
 current_explanation:=jsonb_set(current_explanation,ARRAY['unverified',p_index::text,'verdict'],p_verdict,true);
 UPDATE auto_dev_runs SET explanation=current_explanation WHERE id=p_run_id;
 RETURN current_explanation;
END $$;
REVOKE ALL ON FUNCTION public.save_run_verdict(uuid,integer,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.save_run_verdict(uuid,integer,jsonb,jsonb) TO service_role;


-- ═══════════════════════════ 20260913_26_pipeline_grants.sql ═══════════════════════════

-- 파이프라인 RPC 권한 정리 — service_role 만 남긴다.
--
-- 왜 필요한가: Supabase 는 **새로 만든 함수에 anon·authenticated EXECUTE 를 기본 부여**한다.
-- `20260913_10` 은 마지막에 `REVOKE … FROM PUBLIC, anon, authenticated` 를 갖고 있어 안전했지만,
-- `_11`(create/claim/complete/record/save_pipeline_run) · `_12`(retry_exhausted_classification) ·
-- `_23`(assert_pipeline_run_lease, 재정의된 run 함수들) 은 그 줄이 없었다.
-- 프로덕션 적용 직후 실측에서 8개 함수가 anon 에 열려 있었다 — `anon` 키는 브라우저에 공개되므로
-- 누구나 실행을 가로채거나(claim/complete/save_pipeline_run) 재분류를 강제해(retry_…) 토큰을 태울 수 있었다.
--
-- ⚠️ `REVOKE … FROM PUBLIC` 만으로는 안 좁혀진다. anon·authenticated 를 **명시적으로** 회수해야 한다.
-- 서버는 service_role 로만 부르므로 회수해도 동작은 그대로다.
--
-- 이름으로 도는 이유: 같은 이름이 여러 시그니처로 재정의돼 있어(`claim_pipeline_run` 등
-- `_11` 과 `_23` 이 각각 만든 판) 인자를 손으로 적으면 하나를 빠뜨린다.
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
    WHERE ns.nspname = 'public'
      AND (p.proname LIKE 'pipeline%' OR p.proname IN (
        'claim_response_email','retry_exhausted_classification','confirm_widget_resolution',
        'claim_handoff_email','save_run_verdict','create_pipeline_run','claim_pipeline_run',
        'complete_pipeline_run','record_pipeline_attempt','save_pipeline_run','assert_pipeline_run_lease'))
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', r.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', r.sig);
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';


-- ═══════════════════════════ 20260914_01_unverified_publication.sql ═══════════════════════════

-- 검증 프로필이 없는 실행도 발행을 «확정»할 수 있게 한다 (2026-09-14).
--
-- 왜: 검증 프로필은 제보 하나마다 사람이 손으로 쓰는 것이고 생성하는 코드가 없다.
-- 앱은 프로필이 없으면 검증 없이 PR 을 열고 validation_status='unverifiable' 로 남기는데,
-- 이 함수가 'validated' 만 받으면 PR 이 GitHub 에 «만들어진 뒤» 예외가 난다 —
-- run 은 failed, pr_url 은 NULL, 레포엔 고아 PR. 재시도해도 같은 자리에서 또 실패한다.
-- 그러면 앱 안 PR 검토·반영·머지 감지·되돌림·메일이 전부 도달하지 못한다.
--
-- 강한 경로(validation_status='validated')의 검사식은 «한 글자도» 바꾸지 않았다.
-- 아래 ELSIF 가지 하나만 새로 열었다.
CREATE OR REPLACE FUNCTION complete_pipeline_run(p_id uuid,p_token uuid,p_result jsonb,p_duration integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r auto_dev_runs;
BEGIN
 SELECT * INTO STRICT r FROM auto_dev_runs WHERE id=p_id FOR UPDATE;
 IF r.status<>'in_progress' OR r.lease_token IS DISTINCT FROM p_token OR r.lease_until IS NULL OR r.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'execution_lease_lost'; END IF;
 IF r.publication_status<>'pending' OR p_result->>'pr_url' IS NULL THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 IF r.validation_status='validated' THEN
  -- 종전 그대로 — 증거와 발행 의사가 서로를 묶어야 한다.
  IF NOT coalesce(r.validation_evidence @> '{"status":"validated"}'::jsonb,false)
  OR NOT coalesce((r.validation_evidence->>'patchDigest') ~ '^[a-f0-9]{64}$',false)
  OR NOT coalesce((r.validation_evidence->>'profileDigest') ~ '^[a-f0-9]{64}$',false)
  OR NOT coalesce((r.validation_evidence->>'baseSha') ~ '^[a-f0-9]{40}$',false)
  OR r.validation_evidence->>'patchDigest' IS DISTINCT FROM r.publication_intent->>'patchDigest'
  OR r.validation_evidence->>'profileDigest' IS DISTINCT FROM r.publication_intent->>'profileDigest'
  OR r.validation_evidence->>'baseSha' IS DISTINCT FROM r.publication_intent->>'baseSha'
  OR r.validation_evidence->>'runId' IS DISTINCT FROM p_id::text THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 ELSIF r.validation_status='unverifiable' THEN
  -- 이 제보를 겨냥한 검증 프로필이 없어 증거가 «없다».
  -- 증거를 지어낸 run 은 여기로 못 온다 — evidence 는 반드시 NULL 이어야 한다.
  -- 묶을 증거가 없으므로 발행 의사가 스스로 온전해야 하고,
  -- 프로필 자리엔 digest(null) 이 박혀 있어야 한다(앱의 UNVERIFIED_PROFILE_DIGEST 와 같은 값).
  -- 이 값은 sha256('null') 이고 프로필 객체는 늘 '{...}' 로 직렬화되므로 서로 겹칠 수 없다.
  IF r.validation_evidence IS NOT NULL
  OR r.publication_intent->>'profileDigest' IS DISTINCT FROM '74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b'
  OR NOT coalesce((r.publication_intent->>'patchDigest') ~ '^[a-f0-9]{64}$',false)
  OR NOT coalesce((r.publication_intent->>'baseSha') ~ '^[a-f0-9]{40}$',false)
  OR r.publication_intent->>'runId' IS DISTINCT FROM p_id::text THEN RAISE EXCEPTION 'publication_evidence_mismatch'; END IF;
 ELSE
  -- 그 밖의 상태(failed·stopped·NULL)로는 발행을 확정할 수 없다.
  RAISE EXCEPTION 'publication_evidence_mismatch';
 END IF;
 UPDATE auto_dev_runs SET status='completed',publication_status='published',pr_url=p_result->>'pr_url',pr_number=(p_result->>'pr_number')::integer,
 files_changed=p_result->'files_changed',explanation=p_result->'explanation',duration_ms=p_duration,error_message=NULL,stop_reason=NULL WHERE id=p_id;
 IF r.group_id IS NOT NULL THEN UPDATE insight_groups SET status='pr_created' WHERE id=r.group_id AND status='open'; END IF;
 RETURN true;
END $$;
-- Supabase 는 새 함수에 anon·authenticated EXECUTE 를 기본 부여한다. PUBLIC 회수만으로는 안 좁혀진다.
REVOKE ALL ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION complete_pipeline_run(uuid,uuid,jsonb,integer) TO service_role;


-- ═══════════════════════════ 20260916_01_confirm_changed.sql ═══════════════════════════

-- 되돌림 확인 RPC 가 「값이 실제로 바뀌었는지」를 알려준다.
--
-- 왜: 「아직 그대로예요」를 누르면 라우트가 운영자에게 알림을 보낸다. 그런데 이 RPC 는 멱등이라
-- 같은 값을 다시 받으면 아무것도 안 바꾸고 기존 값을 그대로 돌려줬다 — 라우트가 「바뀌었나」를
-- 알 수 없어 요청마다 발송기를 깨웠다. 메일은 발송기의 상한(대화당 1시간 1통)이 막지만,
-- 상한에 걸려 돌아 나오기까지 DB 왕복 5회와 배타 잠금 2개가 매번 돌았다.
-- 게다가 이 라우트에는 방문자 속도제한이 사실상 없다 — `visitorRateExceeded` 가 `messages` 행을
-- 세는데 확인 요청은 메시지를 만들지 않기 때문이다(IP 60회/분만 남는다).
--
-- 시그니처·반환 타입은 그대로다(jsonb 에 키 하나 추가). 구버전 앱은 이 키를 그냥 무시하므로
-- 배포 순서를 타지 않는다 — 마이그레이션을 먼저 적용해도 안전하다.
CREATE OR REPLACE FUNCTION confirm_widget_resolution(p_bot_id uuid, p_visitor_id uuid, p_response_id uuid, p_confirmation text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r responses; run auto_dev_runs; changed_at timestamptz; did_change boolean := false;
BEGIN
 IF p_confirmation IS NOT NULL AND p_confirmation NOT IN ('fixed','not_fixed') THEN RAISE EXCEPTION 'invalid_confirmation'; END IF;
 SELECT response.* INTO r FROM responses response
 JOIN conversations c ON c.id=response.conversation_id AND c.bot_id=response.bot_id
 JOIN bots b ON b.id=response.bot_id
 JOIN auto_dev_runs a ON a.id=response.auto_dev_run_id AND a.bot_id=response.bot_id
 WHERE response.id=p_response_id AND response.bot_id=p_bot_id
 AND c.source='web' AND c.external_user_id=p_visitor_id::text
 AND b.status<>'paused' AND response.response_type='loop_closed'
 AND response.delivered_at IS NOT NULL AND a.merged_at IS NOT NULL
 FOR UPDATE OF response;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_confirmation IS NOT NULL AND r.user_confirmation IS DISTINCT FROM p_confirmation THEN
  did_change := true;
  changed_at:=clock_timestamp();
  UPDATE responses SET user_confirmation=p_confirmation,user_confirmed_at=changed_at WHERE id=r.id;
  INSERT INTO response_confirmation_history(response_id,confirmation,confirmed_at) VALUES(r.id,p_confirmation,changed_at);
  IF p_confirmation='not_fixed' THEN
   SELECT * INTO run FROM auto_dev_runs WHERE id=r.auto_dev_run_id;
   UPDATE insight_groups SET follow_up_pending=true WHERE bot_id=p_bot_id AND id=coalesce(run.group_id,(SELECT group_id FROM insights WHERE id=run.insight_id AND bot_id=p_bot_id));
   UPDATE conversations SET escalated_at=changed_at WHERE id=r.conversation_id AND bot_id=p_bot_id;
  END IF;
  r.user_confirmation:=p_confirmation; r.user_confirmed_at:=changed_at;
 END IF;
 RETURN jsonb_build_object('responseId',r.id,'confirmation',r.user_confirmation,'confirmedAt',r.user_confirmed_at,'changed',did_change);
END $$;
REVOKE ALL ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) TO service_role;


-- ═══════════════════════════ 20260916_02_run_lease_300s.sql ═══════════════════════════

-- 실행 리스 240 → 300초 (2026-09-16).
--
-- 리스는 클레임 때 한 번 정해지고 «갱신되지 않는다». assert 가 30초 여유를 요구하므로 실효 210초였다.
-- 2-pass 출력 한도를 16,000 → 24,000 으로 올리자(위젯 「화면에서 선택하기」가 컴포넌트 파일을 후보에 더해
-- page.tsx 28KB + 컴포넌트 재작성) 2-pass 가 216초까지 갔고, 분석은 정답이었는데 마지막 저장에서
-- execution_lease_lost 로 통째로 버려졌다(데모 레포 실측). 라우트의 maxDuration 이 300 이라 그 위로는 어차피 못 간다.
BEGIN;
CREATE OR REPLACE FUNCTION claim_pipeline_run(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE token uuid;
BEGIN
 UPDATE auto_dev_runs SET status='in_progress',lease_until=clock_timestamp()+interval '300 seconds',lease_token=gen_random_uuid()
 WHERE id=p_id AND (status='running' OR (status='in_progress' AND lease_until<clock_timestamp())
 OR (status IN ('failed','stopped','unverifiable') AND publication_status='pending' AND publication_intent IS NOT NULL))
 RETURNING lease_token INTO token;
 RETURN token;
END $$;
REVOKE ALL ON FUNCTION claim_pipeline_run(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION claim_pipeline_run(uuid) TO service_role;
COMMIT;


-- ═══════════════════════════ 20260916_03_auto_grouping.sql ═══════════════════════════

-- I-10 자동 묶기 + I-11 대화 힌트 (2026-09-16)
--
-- 자동 묶기는 크론이 아니라(Hobby 는 하루 1회 크론 2개가 끝) 인사이트가 settle 된 요청의
-- after() 안에서 돈다. 판정은 전부 DB 시계(now())로 — 서버리스 인스턴스마다 시계가 조금씩 달라
-- JS Date 로 비교하면 경계에서 어긋난다. 봇당 상태는 grouping_revisions 한 행에 산다.
--
--   due_at      : 이 시각이 지나면 묶어도 된다. 제보가 이어지면 앞으로 밀린다(trailing debounce).
--                 단 first_requested_at + max_wait 를 넘지 못한다 — 80초마다 제보가 오는 봇도 언젠가는 묶인다.
--   waiter_until: 「기다리는 사람」 슬롯. 요청마다 90초를 자면 무인증 요청 하나가 함수를 90초씩 잡는다(보안 리뷰 H2).
--                 슬롯을 먼저 잡은 요청 하나만 자고, 나머지는 due 만 밀고 즉시 돌아간다.
--   lock_until/lock_token : 실행 잠금 + 펜싱. 만료 뒤 남이 잡은 잠금을 옛 실행이 풀지 못한다(보안 리뷰 M2).
--   grouped_at  : 마지막 «성공» 시각. 실패는 여기 안 찍힌다.

-- 1차판(ee7bc5d, 프로덕션엔 적용된 적 없음)의 시그니처. claim 은 반환형이 boolean→uuid 라 CREATE OR REPLACE 가
-- 거부하고(42P13), request/release 는 인자 수가 달라 오버로드로 남으면 호출이 모호해진다. 먼저 지운다.
DROP FUNCTION IF EXISTS auto_grouping_request(uuid, integer);
DROP FUNCTION IF EXISTS auto_grouping_claim(uuid, boolean, integer);
DROP FUNCTION IF EXISTS auto_grouping_release(uuid);

ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_group_due_at timestamptz;
ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_group_first_requested_at timestamptz;
ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_group_waiter_until timestamptz;
ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_group_lock_until timestamptz;
ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_group_lock_token uuid;
ALTER TABLE grouping_revisions ADD COLUMN IF NOT EXISTS auto_grouped_at timestamptz;

-- 요청: 「이 봇은 quiet 초 뒤에 묶어야 한다」 + 대기자 선출.
-- 돌려주는 값: due(예정 시각) · waiter(이 호출이 대기자가 됐는가) · waiter_until(대기자 슬롯 값, 해제 때 펜싱용).
CREATE OR REPLACE FUNCTION auto_grouping_request(
  p_bot_id uuid,
  p_quiet_seconds integer DEFAULT 90,
  p_max_wait_seconds integer DEFAULT 600,
  p_waiter_seconds integer DEFAULT 300
) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE r grouping_revisions; first_at timestamptz; due timestamptz; elected boolean; slot timestamptz;
BEGIN
  INSERT INTO grouping_revisions(bot_id) VALUES (p_bot_id) ON CONFLICT DO NOTHING;
  SELECT * INTO r FROM grouping_revisions WHERE bot_id = p_bot_id FOR UPDATE;
  -- 예정이 없던 상태에서 온 첫 요청이 «이번 회차»의 시작이다. 클레임이 due 를 비우면 다음 회차가 새로 센다.
  first_at := CASE WHEN r.auto_group_due_at IS NULL THEN now() ELSE coalesce(r.auto_group_first_requested_at, now()) END;
  due := least(now() + make_interval(secs => greatest(p_quiet_seconds, 0)),
               first_at + make_interval(secs => greatest(p_max_wait_seconds, 1)));
  elected := r.auto_group_waiter_until IS NULL OR r.auto_group_waiter_until < now();
  slot := CASE WHEN elected THEN now() + make_interval(secs => greatest(p_waiter_seconds, 1)) ELSE r.auto_group_waiter_until END;
  UPDATE grouping_revisions
     SET auto_group_due_at = due, auto_group_first_requested_at = first_at, auto_group_waiter_until = slot
   WHERE bot_id = p_bot_id;
  RETURN jsonb_build_object('due', due, 'waiter', elected, 'waiter_until', slot);
END $$;

-- 대기자 슬롯 반납. 자기 슬롯 값일 때만 — 만료 뒤 새로 뽑힌 대기자의 슬롯을 옛 대기자가 지우지 않는다.
CREATE OR REPLACE FUNCTION auto_grouping_waiter_release(p_bot_id uuid, p_waiter_until timestamptz)
RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  UPDATE grouping_revisions SET auto_group_waiter_until = NULL
   WHERE bot_id = p_bot_id AND auto_group_waiter_until = p_waiter_until;
  RETURN FOUND;
END $$;

-- 클레임: due 가 지났고(또는 p_require_due=false) 잠금이 없거나 만료됐으면 잠그고 토큰을 준다. 아니면 NULL.
-- due 와 회차 시작을 비우는 것도 여기서 — 같은 요청을 두 번 실행하지 않는다. 대기자 슬롯도 비운다(일은 지금 하니까).
CREATE OR REPLACE FUNCTION auto_grouping_claim(p_bot_id uuid, p_require_due boolean DEFAULT true, p_lock_seconds integer DEFAULT 150)
RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$
DECLARE token uuid := gen_random_uuid();
BEGIN
  INSERT INTO grouping_revisions(bot_id) VALUES (p_bot_id) ON CONFLICT DO NOTHING;
  UPDATE grouping_revisions
     SET auto_group_lock_until = now() + make_interval(secs => greatest(p_lock_seconds, 1)),
         auto_group_lock_token = token,
         auto_group_due_at = NULL,
         auto_group_first_requested_at = NULL,
         auto_group_waiter_until = NULL
   WHERE bot_id = p_bot_id
     AND (auto_group_lock_until IS NULL OR auto_group_lock_until < now())
     AND (NOT p_require_due OR (auto_group_due_at IS NOT NULL AND auto_group_due_at <= now()));
  IF FOUND THEN RETURN token; END IF;
  RETURN NULL;
END $$;

-- 해제: 자기 토큰일 때만 잠금을 푼다. 성공이면 grouped_at 을 찍고, 실패면 due 를 다시 심는다(재무장) —
-- 클레임이 due 를 비웠으므로 여기서 안 심으면 실패한 봇은 다음 제보나 사람 손이 올 때까지 영영 안 묶인다(리뷰 3건이 같은 지적).
-- 그사이 새 제보가 due 를 이미 심었으면 그 값을 존중한다.
CREATE OR REPLACE FUNCTION auto_grouping_release(p_bot_id uuid, p_token uuid, p_ok boolean DEFAULT true, p_retry_seconds integer DEFAULT 600)
RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$
BEGIN
  UPDATE grouping_revisions
     SET auto_group_lock_until = NULL,
         auto_group_lock_token = NULL,
         auto_grouped_at = CASE WHEN p_ok THEN now() ELSE auto_grouped_at END,
         auto_group_due_at = CASE WHEN p_ok THEN auto_group_due_at
                                  ELSE coalesce(auto_group_due_at, now() + make_interval(secs => greatest(p_retry_seconds, 1))) END,
         auto_group_first_requested_at = CASE WHEN p_ok THEN auto_group_first_requested_at
                                              ELSE coalesce(auto_group_first_requested_at, now()) END
   WHERE bot_id = p_bot_id AND auto_group_lock_token = p_token;
  RETURN FOUND;
END $$;

-- I-11: 같은 대화의 제보는 이어 말한 것일 가능성이 높다 — 모델이 그걸 볼 수 있게 대화 id 를 싣는다.
-- 시그니처 불변 → 기존 GRANT 유지. 스냅샷의 나머지 로직은 20260913_10 그대로.
CREATE OR REPLACE FUNCTION pipeline_group_snapshot(p_bot_id uuid,p_limit integer DEFAULT 40)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE rev bigint; existing jsonb; candidates jsonb; pending integer;
BEGIN
 INSERT INTO grouping_revisions(bot_id) VALUES(p_bot_id) ON CONFLICT DO NOTHING;
 SELECT revision INTO rev FROM grouping_revisions WHERE bot_id=p_bot_id FOR UPDATE;
 IF (SELECT count(*) FROM insight_groups WHERE bot_id=p_bot_id)>500 THEN RAISE EXCEPTION 'grouping_capacity_requires_partition'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(g)),'[]') INTO existing FROM (SELECT id,title,summary,category,status FROM insight_groups WHERE bot_id=p_bot_id ORDER BY created_at,id) g;
 SELECT count(*) INTO pending FROM insights WHERE bot_id=p_bot_id AND group_id IS NULL AND category IN ('bug','ux','feature_request');
 SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]') INTO candidates FROM (
   SELECT i.id, i.category, i.summary, m.conversation_id
     FROM insights i LEFT JOIN messages m ON m.id = i.message_id
    WHERE i.bot_id=p_bot_id AND i.group_id IS NULL AND i.category IN ('bug','ux','feature_request')
    ORDER BY i.created_at, i.id LIMIT least(greatest(p_limit,1),40)) i;
 RETURN jsonb_build_object('revision',rev,'existing',existing,'insights',candidates,'pending',pending);
END $$;

-- Supabase 는 새 함수에 anon·authenticated EXECUTE 를 기본 부여한다(20260913_26 교훈). 넷 다 회수.
REVOKE ALL ON FUNCTION
  auto_grouping_request(uuid,integer,integer,integer),
  auto_grouping_waiter_release(uuid,timestamptz),
  auto_grouping_claim(uuid,boolean,integer),
  auto_grouping_release(uuid,uuid,boolean,integer)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION
  auto_grouping_request(uuid,integer,integer,integer),
  auto_grouping_waiter_release(uuid,timestamptz),
  auto_grouping_claim(uuid,boolean,integer),
  auto_grouping_release(uuid,uuid,boolean,integer)
  TO service_role;

