-- ═══════════════════════════ 20260916_05_handoff_requested.sql ═══════════════════════════

-- 「상담원에게 전달됐어요」는 방문자가 직접 부른 경우에만 (2026-09-16, ny 결정).
--
-- 왜: conversations.escalated_at 한 칸이 두 뜻을 겸했다 — 받은편지함 「담당자 확인 필요」 배지(운영자용)와
-- 위젯 하단 「상담원에게 전달됐어요」 상태 줄(방문자용). 그런데 이 칸은 AI 가 escalate:true 만 켜도
-- 찍힌다. 「여기가 이상」 같은 버그 제보에 AI 가 평범하게 되묻는 답을 하면서도 «팀 전달 필요» 플래그를
-- 켜면, 방문자는 아무것도 안 눌렀는데 하단이 「전달됐어요」로 바뀌고 「상담원 연결」 버튼이 사라졌다.
--
-- 그래서 «방문자가 직접 부른 시각»을 따로 둔다. 위젯의 escalated 는 이 칸만 본다. escalated_at 은
-- 종전대로 넓은 뜻(AI 물러남 포함)으로 받은편지함 배지에 쓴다. 운영자 답장은 둘 다 지운다.
--
-- 찍히는 경로 세 곳: 「상담원 연결」 버튼(escalate 라우트), 대기 문구 밑 제안 칩(같은 라우트),
-- 「아직 그대로예요」(아래 RPC — 운영자가 고쳤다고 답한 뒤 방문자가 누른 명시적 요청이라 같이 찍는다).
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS handoff_requested_at TIMESTAMPTZ;

-- 이미 escalated 인 대화 중 방문자가 직접 부른 흔적(handoff_at 메시지)이 있는 건 새 칸도 채워 둔다.
-- 버튼만 누른 경우(메시지 없음)는 구분할 수 없어 비워 둔다 — 배지는 남고 위젯 상태 줄만 꺼진다.
UPDATE conversations c SET handoff_requested_at = c.escalated_at
 WHERE c.escalated_at IS NOT NULL AND c.handoff_requested_at IS NULL
 AND EXISTS (SELECT 1 FROM messages m WHERE m.conversation_id = c.id AND m.handoff_at IS NOT NULL);

-- 20260916_01 과 같고, not_fixed 가 handoff_requested_at 도 찍는다는 한 줄만 다르다.
CREATE OR REPLACE FUNCTION confirm_widget_resolution(p_bot_id uuid, p_visitor_id uuid, p_response_id uuid, p_confirmation text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r responses; run auto_dev_runs; changed_at timestamptz; did_change boolean := false;
BEGIN
 IF p_confirmation IS NOT NULL AND p_confirmation NOT IN ('fixed','not_fixed') THEN RAISE EXCEPTION 'invalid_confirmation'; END IF;
 SELECT response.* INTO r FROM responses response
 JOIN conversations c ON c.id=response.conversation_id AND c.bot_id=response.bot_id
 JOIN bots b ON b.id=response.bot_id
 JOIN auto_dev_runs a ON a.id=response.auto_dev_run_id AND a.bot_id=response.bot_id
 WHERE response.id=p_response_id AND response.bot_id=p_bot_id
 AND c.source='web' AND c.external_user_id=p_visitor_id::text
 AND b.status<>'paused' AND response.response_type='loop_closed'
 AND response.delivered_at IS NOT NULL AND a.merged_at IS NOT NULL
 FOR UPDATE OF response;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_confirmation IS NOT NULL AND r.user_confirmation IS DISTINCT FROM p_confirmation THEN
  did_change := true;
  changed_at:=clock_timestamp();
  UPDATE responses SET user_confirmation=p_confirmation,user_confirmed_at=changed_at WHERE id=r.id;
  INSERT INTO response_confirmation_history(response_id,confirmation,confirmed_at) VALUES(r.id,p_confirmation,changed_at);
  IF p_confirmation='not_fixed' THEN
   SELECT * INTO run FROM auto_dev_runs WHERE id=r.auto_dev_run_id;
   UPDATE insight_groups SET follow_up_pending=true WHERE bot_id=p_bot_id AND id=coalesce(run.group_id,(SELECT group_id FROM insights WHERE id=run.insight_id AND bot_id=p_bot_id));
   UPDATE conversations SET escalated_at=changed_at, handoff_requested_at=changed_at WHERE id=r.conversation_id AND bot_id=p_bot_id;
  END IF;
  r.user_confirmation:=p_confirmation; r.user_confirmed_at:=changed_at;
 END IF;
 RETURN jsonb_build_object('responseId',r.id,'confirmation',r.user_confirmation,'confirmedAt',r.user_confirmed_at,'changed',did_change);
END $$;
REVOKE ALL ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION confirm_widget_resolution(uuid,uuid,uuid,text) TO service_role;


-- ═══════════════════════════ 20260917_01_group_snapshot_recent.sql ═══════════════════════════

-- B1 기존 묶음 대조 (2026-09-17) — 스냅샷이 싣는 기존 묶음을 «최근 30개» 로 자른다.
--
-- 왜: `pipeline_group_snapshot` 은 이 봇의 묶음을 «전부» 실어 줬다(상한은 500개 초과를 막는 검사뿐).
-- 그게 그대로 묶기 프롬프트에 들어간다. 묶음이 쌓일수록 입력이 커지고, 입력이 커지면 모델이
-- 목록을 대충 읽어 기존 묶음 대조 자체가 나빠진다(백로그 B1 「주의」). 30 은 JS 쪽
-- `EXISTING_GROUPS_LIMIT` 과 같은 값이다 — 한쪽만 바꾸면 즉답(F1)과 묶기가 다른 목록을 본다.
--
-- 순서: 최근 30개를 «고른 뒤» 오래된 것부터 담는다. 고를 때는 최신순이어야 최근 것이 남고,
-- 담을 때는 예전과 같은 순서(created_at, id)여야 프롬프트 모양이 안 바뀐다.
-- 시그니처·나머지 로직은 20260916_03 그대로 → 기존 GRANT 유지.

CREATE OR REPLACE FUNCTION pipeline_group_snapshot(p_bot_id uuid,p_limit integer DEFAULT 40)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE rev bigint; existing jsonb; candidates jsonb; pending integer;
BEGIN
 INSERT INTO grouping_revisions(bot_id) VALUES(p_bot_id) ON CONFLICT DO NOTHING;
 SELECT revision INTO rev FROM grouping_revisions WHERE bot_id=p_bot_id FOR UPDATE;
 IF (SELECT count(*) FROM insight_groups WHERE bot_id=p_bot_id)>500 THEN RAISE EXCEPTION 'grouping_capacity_requires_partition'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(g) - 'created_at' ORDER BY g.created_at, g.id),'[]') INTO existing FROM (
   SELECT id,title,summary,category,status,created_at
     FROM insight_groups WHERE bot_id=p_bot_id
    ORDER BY created_at DESC, id DESC LIMIT 30) g;
 SELECT count(*) INTO pending FROM insights WHERE bot_id=p_bot_id AND group_id IS NULL AND category IN ('bug','ux','feature_request');
 SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]') INTO candidates FROM (
   SELECT i.id, i.category, i.summary, m.conversation_id
     FROM insights i LEFT JOIN messages m ON m.id = i.message_id
    WHERE i.bot_id=p_bot_id AND i.group_id IS NULL AND i.category IN ('bug','ux','feature_request')
    ORDER BY i.created_at, i.id LIMIT least(greatest(p_limit,1),40)) i;
 RETURN jsonb_build_object('revision',rev,'existing',existing,'insights',candidates,'pending',pending);
END $$;

NOTIFY pgrst, 'reload schema';


-- ═══════════════════════════ 20260925_01_widget_shots.sql ═══════════════════════════

-- I-55 「화면에서 선택하기」 스크린샷 (2026-09-25). 기획: docs/07-위젯/화면에서-선택-스크린샷-기획-2026-09-25.md
--
-- 방문자가 요소를 짚는 순간 위젯이 뷰포트를 촬영해 비공개 버킷에 올린다. 이 표는 그 한 장의 기록이다.
-- - 업로드 시점엔 message_id 가 NULL 이다. 메시지를 보낼 때 «같은 봇·같은 방문자·아직 안 붙은» 행만 붙인다
--   (남의 shotId 를 붙여 남의 화면을 자기 제보로 끌어오는 경로 차단).
-- - bot 이 지워지면 행은 CASCADE 로 사라지지만 **Storage 객체는 안 지워진다** — 봇 삭제 라우트가 먼저 폴더를 비운다.
-- - message 가 지워지면 SET NULL — 고아가 되고 하루 1회 정리 단계가 치운다.
-- - RLS on, 정책 없음(anon 전면 차단). 서버는 service_role 로만 만진다.
-- 코드보다 먼저 적용한다(추가 전용).

CREATE TABLE IF NOT EXISTS widget_shots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  bot_id uuid NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  visitor_id text NOT NULL,
  message_id uuid REFERENCES messages(id) ON DELETE SET NULL,
  storage_path text NOT NULL UNIQUE,
  mime text NOT NULL CHECK (mime IN ('image/webp', 'image/jpeg')),
  bytes integer NOT NULL CHECK (bytes > 0 AND bytes <= 1048576),
  width integer NOT NULL CHECK (width > 0 AND width <= 2560),
  height integer NOT NULL CHECK (height > 0 AND height <= 2560),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 봇 하루 상한·방문자 분당 상한 계수
CREATE INDEX IF NOT EXISTS idx_widget_shots_bot_created ON widget_shots (bot_id, created_at);
CREATE INDEX IF NOT EXISTS idx_widget_shots_visitor_created ON widget_shots (bot_id, visitor_id, created_at);
-- 운영자 화면이 메시지로 찾는다
CREATE INDEX IF NOT EXISTS idx_widget_shots_message ON widget_shots (message_id) WHERE message_id IS NOT NULL;
-- 고아 정리
CREATE INDEX IF NOT EXISTS idx_widget_shots_orphan ON widget_shots (created_at) WHERE message_id IS NULL;

ALTER TABLE widget_shots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON widget_shots FROM anon, authenticated;

-- 비공개 버킷. 공개 URL 없음 — 운영자 라우트가 10분짜리 서명 URL 만 싣는다.
-- 크기·형식 상한은 라우트가 먼저 보지만 버킷에도 한 번 더 건다.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('widget-shots', 'widget-shots', false, 1048576, ARRAY['image/webp', 'image/jpeg'])
ON CONFLICT (id) DO UPDATE
  SET public = false,
      file_size_limit = EXCLUDED.file_size_limit,
      allowed_mime_types = EXCLUDED.allowed_mime_types;


-- ═══════════════════════════ 20260925_02_widget_shot_reserve.sql ═══════════════════════════

-- I-55 보안 리뷰 M1·L1 (2026-09-25) — 업로드 상한을 «먼저 세고 나중에 쓰는» 구조에서 «잠그고 세고 예약»으로.
--
-- 예전: 행을 센 뒤 1MB 수신 → Storage 업로드 → INSERT. 그 사이 수백 ms~수 초 동안 동시 요청 50개가 모두
-- count=0 을 보고 통과했다(서버리스 인스턴스가 늘면 인메모리 IP 상한도 못 막는다) → 「봇 하루 300장」이 상한이 아니었다.
-- 이제: 봇 단위 advisory 잠금 안에서 세고, 통과하면 그 자리에서 행을 INSERT(예약)한다. 예약 행이 곧바로
-- 계수에 잡혀 동시 요청 창이 사라진다. 업로드는 예약 «뒤»이고, 실패하면 앱이 행을 지운다.
-- 함수가 업로드 도중 죽어도 행이 남으니 정리 단계가 찾는다(행 없는 객체가 생기지 않는다 — L1 ①).
-- 반환: NULL = 예약됨, 'visitor' / 'bot' = 상한. service_role 만 실행한다.

CREATE OR REPLACE FUNCTION reserve_widget_shot(
  p_id uuid, p_bot uuid, p_visitor text, p_path text, p_mime text, p_bytes integer, p_width integer, p_height integer,
  p_visitor_limit integer, p_bot_limit integer
) RETURNS text
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('widget_shots:' || p_bot::text));
  IF (SELECT count(*) FROM widget_shots
        WHERE bot_id = p_bot AND visitor_id = p_visitor AND created_at > now() - interval '1 minute') >= p_visitor_limit THEN
    RETURN 'visitor';
  END IF;
  IF (SELECT count(*) FROM widget_shots
        WHERE bot_id = p_bot AND created_at > now() - interval '24 hours') >= p_bot_limit THEN
    RETURN 'bot';
  END IF;
  INSERT INTO widget_shots (id, bot_id, visitor_id, storage_path, mime, bytes, width, height)
  VALUES (p_id, p_bot, p_visitor, p_path, p_mime, p_bytes, p_width, p_height);
  RETURN NULL;
END $$;

REVOKE ALL ON FUNCTION reserve_widget_shot(uuid, uuid, text, text, text, integer, integer, integer, integer, integer)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION reserve_widget_shot(uuid, uuid, text, text, text, integer, integer, integer, integer, integer)
  TO service_role;


-- ═══════════════════════════ 20261009_01_priority_jev.sql ═══════════════════════════

-- Apply before deploying the code. Existing rows remain unscored/unattributed.
ALTER TABLE insights ADD COLUMN IF NOT EXISTS classified_by text;
ALTER TABLE insights ADD COLUMN IF NOT EXISTS classify_confidence real;
ALTER TABLE insight_groups ADD COLUMN IF NOT EXISTS impact_core boolean;
ALTER TABLE insight_groups ADD COLUMN IF NOT EXISTS impact_reason text;
ALTER TABLE insight_groups ADD COLUMN IF NOT EXISTS impact_scored_at timestamptz;

-- Preserve atomic source membership, lease checks, and extension behavior.
CREATE OR REPLACE FUNCTION pipeline_settle_insight(p_bot_id uuid,p_message_id uuid,p_insight jsonb,p_extend_id uuid DEFAULT NULL,p_lease uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE m messages; iid uuid; existing_id uuid; target insights; original_conversation uuid;
BEGIN
 SELECT * INTO m FROM messages WHERE id=p_message_id AND bot_id=p_bot_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'message_not_saved'; END IF;
 IF p_lease IS NOT NULL AND (m.classification_lease IS DISTINCT FROM p_lease OR m.classification_state <> 'processing') THEN RAISE EXCEPTION 'stale_classification_lease'; END IF;
 SELECT insight_id INTO existing_id FROM insight_message_sources WHERE message_id=p_message_id;
 IF existing_id IS NOT NULL THEN
   UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
   RETURN jsonb_build_object('id',existing_id,'created',false);
 END IF;
 -- Null classification with a known extension is provenance, not permission to rewrite metadata.
 IF p_extend_id IS NOT NULL AND (p_insight IS NULL OR p_insight = 'null'::jsonb) THEN
   -- Same target lock as create_pipeline_run; grouped evidence is also protected by the row lock.
   PERFORM pg_advisory_xact_lock(hashtextextended(p_bot_id::text||':'||p_extend_id::text,0));
   SELECT * INTO target FROM insights WHERE id=p_extend_id AND bot_id=p_bot_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'source_extension_unavailable'; END IF;
   SELECT conversation_id INTO original_conversation FROM messages WHERE id=target.message_id AND bot_id=p_bot_id;
   IF m.conversation_id IS NULL OR original_conversation IS DISTINCT FROM m.conversation_id
     OR target.group_id IS NOT NULL OR coalesce(cardinality(target.source_message_ids),0)>=50
     OR EXISTS(SELECT 1 FROM auto_dev_runs WHERE insight_id=p_extend_id)
   THEN RAISE EXCEPTION 'source_extension_unavailable'; END IF;
   UPDATE insights SET source_message_ids=array_append(coalesce(source_message_ids,ARRAY[]::uuid[]),p_message_id)
     WHERE id=p_extend_id RETURNING id INTO iid;
 ELSIF p_insight IS NOT NULL AND p_insight <> 'null'::jsonb THEN
   IF p_extend_id IS NOT NULL THEN
     -- Existing implementation protects published/grouped evidence. A blocked extension becomes a new report for grouping.
     SELECT extend_insight(p_bot_id,p_extend_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false)) INTO iid;
   END IF;
   IF iid IS NULL THEN
     INSERT INTO insights(bot_id,message_id,category,summary,sentiment,follow_up_needed,classified_by,classify_confidence)
     VALUES(p_bot_id,p_message_id,p_insight->>'category',p_insight->>'summary',p_insight->>'sentiment',coalesce((p_insight->>'follow_up_needed')::boolean,false),p_insight->>'classified_by',(p_insight->>'classify_confidence')::real) RETURNING id INTO iid;
   END IF;
 END IF;
 UPDATE messages SET classification_state='done',classification_lease=NULL,classification_error=NULL WHERE id=p_message_id;
 RETURN jsonb_build_object('id',iid,'created',iid IS NOT NULL AND p_extend_id IS DISTINCT FROM iid);
END $$;

REVOKE EXECUTE ON FUNCTION pipeline_settle_insight(uuid,uuid,jsonb,uuid,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION pipeline_settle_insight(uuid,uuid,jsonb,uuid,uuid) TO service_role;


-- ═══════════════════════════ 20261009_02_draft_pr_gate_lock.sql ═══════════════════════════

-- Cross-process PR gate lease. Apply through the normal migration process; no run columns change.
BEGIN;
CREATE TABLE IF NOT EXISTS public.draft_pr_gate_locks (
  key text PRIMARY KEY,
  owner uuid NOT NULL,
  expires_at timestamptz NOT NULL
);
ALTER TABLE public.draft_pr_gate_locks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.draft_pr_gate_locks FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.claim_draft_pr_gate(p_key text, p_owner uuid, p_ttl_seconds integer DEFAULT 300)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF p_key IS NULL OR p_key = '' OR p_owner IS NULL OR p_ttl_seconds IS NULL OR p_ttl_seconds <= 30 THEN
    RETURN false;
  END IF;
  INSERT INTO public.draft_pr_gate_locks(key, owner, expires_at)
  VALUES (p_key, p_owner, clock_timestamp() + make_interval(secs => p_ttl_seconds))
  ON CONFLICT (key) DO UPDATE
    SET owner = EXCLUDED.owner, expires_at = EXCLUDED.expires_at
    WHERE draft_pr_gate_locks.expires_at <= clock_timestamp();
  RETURN FOUND;
END $$;

CREATE OR REPLACE FUNCTION public.owns_draft_pr_gate(p_key text, p_owner uuid)
RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.draft_pr_gate_locks
    WHERE key = p_key AND owner = p_owner AND expires_at >= clock_timestamp() + interval '30 seconds'
  );
$$;

CREATE OR REPLACE FUNCTION public.release_draft_pr_gate(p_key text, p_owner uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  DELETE FROM public.draft_pr_gate_locks WHERE key = p_key AND owner = p_owner;
  RETURN FOUND;
END $$;

REVOKE ALL ON FUNCTION public.claim_draft_pr_gate(text, uuid, integer) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.owns_draft_pr_gate(text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.release_draft_pr_gate(text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_draft_pr_gate(text, uuid, integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.owns_draft_pr_gate(text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.release_draft_pr_gate(text, uuid) TO service_role;
COMMIT;


-- ═══════════════════════════ 20261019_01_paypal_foundation.sql ═══════════════════════════

-- 2026-10-19 PayPal foundation (PayPal AI Hackathon — design v2 §3 connection, §4 guardrail, §9 demo).
--
-- Additive only: nothing the Korean production deployment relies on changes shape.
--  1) bots      — per-bot PayPal credentials (same encrypt-and-show-last4 pattern as the LLM key),
--                 refund limits the guardrail re-reads at execution time, and a demo flag.
--  2) bot_members — approvers who are not the owner. Judges press "Try the demo bot" and land here.
--  3) products / paypal_orders / payment_actions / paypal_webhook_events.
--  4) payment_action_open_refund() — the guardrail decision and the write-ahead row in ONE statement,
--     so two concurrent "refund me" messages for the same capture can never both execute.
--
-- RLS convention (20260905_01, 20260910_01): RLS on + zero policies = the public anon key is blocked
-- outright. Every app path reaches these tables through service_role, which bypasses RLS.

-- ── 1. bots: PayPal connection ────────────────────────────────────────────────────────────
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_client_id        TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_secret_encrypted TEXT;        -- AES-256-GCM (lib/utils/crypto.ts); never returned by any route
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_secret_last4     TEXT;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_env              TEXT NOT NULL DEFAULT 'sandbox';
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_verified_at      TIMESTAMPTZ;  -- last successful OAuth token with these credentials
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_failed_at        TIMESTAMPTZ;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_failed_reason    TEXT;         -- short fixed code, never PayPal's raw error text
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_scopes           TEXT[];       -- `scope` from the token response, for the settings screen
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_webhook_id       TEXT;         -- registered via POST /v1/notifications/webhooks on save
ALTER TABLE bots ADD COLUMN IF NOT EXISTS paypal_paused           BOOLEAN NOT NULL DEFAULT false; -- kill switch: nothing auto-executes while true

-- Refund guardrail limits. Defaults = design v2 §3. The RPC below reads these at decision time —
-- never from the 5-minute bot config cache — so a tightened limit applies to the very next message.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS refund_auto_max_cents   INTEGER NOT NULL DEFAULT 2000;   -- ≤ $20 auto
ALTER TABLE bots ADD COLUMN IF NOT EXISTS refund_auto_days        INTEGER NOT NULL DEFAULT 14;     -- captured within N days
ALTER TABLE bots ADD COLUMN IF NOT EXISTS refund_daily_cap_cents  INTEGER NOT NULL DEFAULT 10000;  -- per bot per UTC day
ALTER TABLE bots ADD COLUMN IF NOT EXISTS refund_per_customer_30d INTEGER NOT NULL DEFAULT 1;
ALTER TABLE bots ADD COLUMN IF NOT EXISTS currency                TEXT NOT NULL DEFAULT 'USD';
ALTER TABLE bots ADD COLUMN IF NOT EXISTS propose_only            BOOLEAN NOT NULL DEFAULT false;  -- "suggest only" mode: every refund waits for approval

-- The one bot whose widget runs on Feedloop's own pricing page. At most one row may carry the flag.
ALTER TABLE bots ADD COLUMN IF NOT EXISTS is_demo                 BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX IF NOT EXISTS idx_bots_single_demo ON bots (is_demo) WHERE is_demo;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'bots_paypal_env_check') THEN
    ALTER TABLE bots ADD CONSTRAINT bots_paypal_env_check CHECK (paypal_env IN ('sandbox', 'live'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'bots_refund_limits_check') THEN
    ALTER TABLE bots ADD CONSTRAINT bots_refund_limits_check CHECK (
      refund_auto_max_cents >= 0 AND refund_auto_days >= 0 AND
      refund_daily_cap_cents >= 0 AND refund_per_customer_30d >= 0
    );
  END IF;
END $$;

-- ── 2. bot_members: approvers besides the owner ──────────────────────────────────────────
-- Ownership stays a single user_id on bots. Members get the operator screens (inbox, dashboard,
-- approvals) through lib/auth/ownership.ts#resolveAccessibleBots; settings routes stay owner-only.
CREATE TABLE IF NOT EXISTS bot_members (
  bot_id     UUID NOT NULL REFERENCES bots(id)  ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role       TEXT NOT NULL DEFAULT 'approver' CHECK (role IN ('approver')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (bot_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_bot_members_user ON bot_members(user_id);
ALTER TABLE bot_members ENABLE ROW LEVEL SECURITY;

-- ── 3a. products: the price table the agent may choose from ──────────────────────────────
-- The LLM only ever picks (product_id, quantity). Amounts come from this row, never from the model.
CREATE TABLE IF NOT EXISTS products (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  bot_id       UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  sku          TEXT NOT NULL,
  name         TEXT NOT NULL,
  description  TEXT,
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  currency     TEXT NOT NULL DEFAULT 'USD',
  active       BOOLEAN NOT NULL DEFAULT true,
  sort_order   INTEGER NOT NULL DEFAULT 0,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (bot_id, sku)
);
CREATE INDEX IF NOT EXISTS idx_products_bot ON products(bot_id, active, sort_order);
ALTER TABLE products ENABLE ROW LEVEL SECURITY;

-- ── 3b. paypal_orders: checkouts we created (pricing page or mid-chat) ───────────────────
-- Keyed by PayPal's order id so the return URL and the webhook update the same row.
CREATE TABLE IF NOT EXISTS paypal_orders (
  order_id        TEXT PRIMARY KEY,
  bot_id          UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,  -- set when bought from the widget
  product_id      UUID REFERENCES products(id) ON DELETE SET NULL,
  quantity        INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
  amount_cents    INTEGER NOT NULL CHECK (amount_cents > 0),
  currency        TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'created'
                  CHECK (status IN ('created', 'approved', 'captured', 'expired', 'failed')),
  capture_id      TEXT,                                                  -- filled on capture; refunds target this
  payer_email     TEXT,                                                  -- what find_my_payment compares against
  payer_id        TEXT,
  approve_url     TEXT,                                                  -- shown as the "Pay with PayPal" card (server data, not LLM text)
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  captured_at     TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_paypal_orders_bot  ON paypal_orders(bot_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_paypal_orders_conv ON paypal_orders(conversation_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_paypal_orders_capture ON paypal_orders(capture_id) WHERE capture_id IS NOT NULL;
ALTER TABLE paypal_orders ENABLE ROW LEVEL SECURITY;

-- ── 3c. payment_actions: every move of money, auto or approved ───────────────────────────
-- Lifecycle: pending → executing → executed | failed   (approval path)
--            executing → executed | failed              (auto path, row is born as executing)
--            pending → rejected | expired               (operator said no / 7 days passed)
-- `id` doubles as the PayPal-Request-Id of the call, so a retry after a crash is idempotent on PayPal's side.
CREATE TABLE IF NOT EXISTS payment_actions (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  bot_id          UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
  conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,
  kind            TEXT NOT NULL CHECK (kind IN ('refund', 'accept_dispute')),
  target_id       TEXT NOT NULL,                       -- capture id (refund) or dispute id (accept_dispute)
  amount_cents    INTEGER CHECK (amount_cents IS NULL OR amount_cents > 0),
  currency        TEXT,
  customer_key    TEXT,                                -- payer email (lower-cased); drives the per-customer cap
  origin          TEXT NOT NULL CHECK (origin IN ('auto', 'approval')),
  status          TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'executing', 'executed', 'failed', 'rejected', 'expired')),
  reason          TEXT,                                -- what the customer said
  guardrail       JSONB,                               -- each check and whether it passed — the approval card shows this
  payload         JSONB,                               -- the request body we sent to PayPal
  result          JSONB,                               -- PayPal's parsed response (no secrets)
  paypal_ref      TEXT,                                -- refund id / dispute action ref
  error           TEXT,
  decided_by      UUID REFERENCES users(id) ON DELETE SET NULL,
  decided_at      TIMESTAMPTZ,
  executed_at     TIMESTAMPTZ,
  reminded_at     TIMESTAMPTZ,                         -- 24h nudge sent
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- One live action per (bot, kind, target). pending/executing/executed count as live; rejected/expired/failed
-- free the slot so a legitimate second attempt is possible after a human said no or PayPal failed.
CREATE UNIQUE INDEX IF NOT EXISTS idx_payment_actions_live_target
  ON payment_actions(bot_id, kind, target_id)
  WHERE status IN ('pending', 'executing', 'executed');
CREATE INDEX IF NOT EXISTS idx_payment_actions_bot_status ON payment_actions(bot_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_payment_actions_conv       ON payment_actions(conversation_id);
ALTER TABLE payment_actions ENABLE ROW LEVEL SECURITY;

-- ── 3d. paypal_webhook_events: dedupe + audit for inbound webhooks ───────────────────────
CREATE TABLE IF NOT EXISTS paypal_webhook_events (
  event_id      TEXT PRIMARY KEY,                       -- PayPal event id; a redelivery hits the PK and is dropped
  bot_id        UUID REFERENCES bots(id) ON DELETE CASCADE,
  event_type    TEXT NOT NULL,
  resource_type TEXT,
  resource_id   TEXT,
  payload       JSONB NOT NULL,
  received_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  processed_at  TIMESTAMPTZ,
  error         TEXT
);
CREATE INDEX IF NOT EXISTS idx_paypal_webhook_events_bot ON paypal_webhook_events(bot_id, received_at DESC);
ALTER TABLE paypal_webhook_events ENABLE ROW LEVEL SECURITY;

-- responses.response_type is free TEXT (init_schema.sql). 'payment' = server-fixed sentences about money
-- (refund done / waiting for approval / declined / failed). Recorded here so the next reader knows the value set.
COMMENT ON COLUMN responses.response_type IS
  'mention | keyword | question | kakao | ai | operator | loop_closed | system | payment';

-- ── 4. Guardrail RPC ─────────────────────────────────────────────────────────────────────
-- Inputs are facts the SERVER read from PayPal (GET /v2/payments/captures/{id}) — never model output.
-- Returns jsonb: { created, auto, action, checks }.
--   created=false → a live action for this capture already exists; `action` is that row. Do not call PayPal.
--   auto=true     → row was inserted as origin=auto, status=executing. Caller must now call PayPal with
--                   PayPal-Request-Id = action.id and then mark executed/failed.
--   auto=false    → row is pending; show the approval card. Nothing moves until an operator decides.
-- Per-bot advisory lock serialises the daily-cap and per-customer arithmetic; the partial unique index is
-- the second line of defence if anything ever bypasses the lock.
CREATE OR REPLACE FUNCTION payment_action_open_refund(
  p_bot_id             uuid,
  p_conversation_id    uuid,
  p_capture_id         text,
  p_amount_cents       integer,
  p_currency           text,
  p_captured_at        timestamptz,
  p_capture_has_refund boolean,
  p_has_dispute        boolean,
  p_customer_key       text,
  p_reason             text
) RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  b                bots%ROWTYPE;
  v_existing       payment_actions%ROWTYPE;
  v_row            payment_actions%ROWTYPE;
  v_daily_cents    integer;
  v_customer_count integer;
  v_checks         jsonb;
  v_auto           boolean;
BEGIN
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN
    RAISE EXCEPTION 'refund amount must be explicit and positive (omitting it would mean a full refund on PayPal)';
  END IF;
  IF p_capture_id IS NULL OR length(p_capture_id) = 0 THEN
    RAISE EXCEPTION 'capture id required';
  END IF;

  SELECT * INTO b FROM bots WHERE id = p_bot_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bot % not found', p_bot_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('payment_actions:' || p_bot_id::text));

  SELECT * INTO v_existing
    FROM payment_actions
   WHERE bot_id = p_bot_id AND kind = 'refund' AND target_id = p_capture_id
     AND status IN ('pending', 'executing', 'executed')
   LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('created', false, 'auto', v_existing.origin = 'auto', 'action', to_jsonb(v_existing));
  END IF;

  SELECT COALESCE(SUM(amount_cents), 0) INTO v_daily_cents
    FROM payment_actions
   WHERE bot_id = p_bot_id AND kind = 'refund' AND status IN ('executing', 'executed')
     AND created_at >= date_trunc('day', now());

  SELECT COUNT(*) INTO v_customer_count
    FROM payment_actions
   WHERE bot_id = p_bot_id AND kind = 'refund' AND status IN ('pending', 'executing', 'executed')
     AND p_customer_key IS NOT NULL AND customer_key = lower(p_customer_key)
     AND created_at >= now() - interval '30 days';

  v_checks := jsonb_build_object(
    'amount_within_max', p_amount_cents <= b.refund_auto_max_cents,
    'within_days',       p_captured_at IS NOT NULL AND p_captured_at >= now() - make_interval(days => b.refund_auto_days),
    'no_prior_refund',   NOT COALESCE(p_capture_has_refund, true),
    'currency_matches',  p_currency IS NOT NULL AND upper(p_currency) = upper(b.currency),
    'daily_cap_ok',      v_daily_cents + p_amount_cents <= b.refund_daily_cap_cents,
    'customer_cap_ok',   v_customer_count < b.refund_per_customer_30d,
    'no_dispute',        NOT COALESCE(p_has_dispute, true),
    'not_propose_only',  NOT b.propose_only,
    'not_paused',        NOT b.paypal_paused
  );
  v_auto := NOT EXISTS (SELECT 1 FROM jsonb_each(v_checks) WHERE value = 'false'::jsonb);

  INSERT INTO payment_actions
    (bot_id, conversation_id, kind, target_id, amount_cents, currency, customer_key, origin, status, reason, guardrail)
  VALUES
    (p_bot_id, p_conversation_id, 'refund', p_capture_id, p_amount_cents, upper(p_currency),
     lower(p_customer_key),
     CASE WHEN v_auto THEN 'auto' ELSE 'approval' END,
     CASE WHEN v_auto THEN 'executing' ELSE 'pending' END,
     p_reason, v_checks)
  RETURNING * INTO v_row;

  RETURN jsonb_build_object('created', true, 'auto', v_auto, 'action', to_jsonb(v_row), 'checks', v_checks);
END
$$;

-- Supabase grants anon/authenticated EXECUTE on new public functions by default (20260913_26). Revoke all three.
REVOKE ALL ON FUNCTION payment_action_open_refund(uuid, uuid, text, integer, text, timestamptz, boolean, boolean, text, text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION payment_action_open_refund(uuid, uuid, text, integer, text, timestamptz, boolean, boolean, text, text)
  TO service_role;

NOTIFY pgrst, 'reload schema';

-- ── Rollback (run by hand, in this order; not executed by the migration) ─────────────────────────
-- Later stage-3 migrations (20261020_01 … 20261021_03) must be rolled back first; their blocks say how.
-- DROP FUNCTION IF EXISTS payment_action_open_refund(uuid, uuid, text, integer, text, timestamptz, boolean, boolean, text, text);
-- DROP TABLE IF EXISTS paypal_webhook_events;
-- DROP TABLE IF EXISTS payment_actions;
-- DROP TABLE IF EXISTS paypal_orders;
-- DROP TABLE IF EXISTS products;
-- DROP TABLE IF EXISTS bot_members;
-- COMMENT ON COLUMN responses.response_type IS 'mention | keyword | question | kakao | ai | operator | loop_closed | system';
-- DROP INDEX IF EXISTS idx_bots_single_demo;
-- ALTER TABLE bots DROP CONSTRAINT IF EXISTS bots_refund_limits_check;
-- ALTER TABLE bots DROP CONSTRAINT IF EXISTS bots_paypal_env_check;
-- ALTER TABLE bots
--   DROP COLUMN IF EXISTS is_demo, DROP COLUMN IF EXISTS propose_only, DROP COLUMN IF EXISTS currency,
--   DROP COLUMN IF EXISTS refund_per_customer_30d, DROP COLUMN IF EXISTS refund_daily_cap_cents,
--   DROP COLUMN IF EXISTS refund_auto_days, DROP COLUMN IF EXISTS refund_auto_max_cents,
--   DROP COLUMN IF EXISTS paypal_paused, DROP COLUMN IF EXISTS paypal_webhook_id, DROP COLUMN IF EXISTS paypal_scopes,
--   DROP COLUMN IF EXISTS paypal_failed_reason, DROP COLUMN IF EXISTS paypal_failed_at, DROP COLUMN IF EXISTS paypal_verified_at,
--   DROP COLUMN IF EXISTS paypal_env, DROP COLUMN IF EXISTS paypal_secret_last4, DROP COLUMN IF EXISTS paypal_secret_encrypted,
